INSERT INTO _n1_b3_guard_0101(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-10-29' AND '2026-11-11' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1615','2026-10-29','閉口','へいこう','질림; 곤란해함; 두 손 듦','相手・状況に困り果てて、どうにもならないと感じること。','毎日のように届く迷惑メールの多さには閉口している。','매일같이 오는 스팸 메일의 양에는 정말 질려 있다.'),
('n1-1625','2026-10-29','船舶','せんぱく','선박','海・川などを航行する船の総称。特に法律・運輸などの分野で用いる。','港では大型船舶の入港に合わせて荷役作業が始まった。','항구에서는 대형 선박 입항에 맞춰 하역 작업이 시작되었다.'),
('n1-1628','2026-10-29','扶養','ふよう','부양','自力で生活することが難しい家族などの生活を経済的に支えること。','税制度では扶養する家族の人数が控除額に影響する場合がある。','세제에서는 부양 가족 수가 공제액에 영향을 주는 경우가 있다.'),
('n1-1630','2026-10-29','傾斜','けいしゃ','경사; 기울기','水平・垂直な基準に対して斜めに傾いていること。また、その角度。','この坂は傾斜が急なので、自転車では注意が必要だ。','이 언덕은 경사가 급해서 자전거로 갈 때 주의가 필요하다.'),
('n1-1634','2026-10-29','根底','こんてい','근저; 밑바탕; 근본','考え・制度・問題などを成り立たせている最も基本的な部分。','この議論の根底には、働き方に対する価値観の違いがある。','이 논의의 밑바탕에는 일하는 방식에 대한 가치관 차이가 있다.'),
('n1-1635','2026-10-29','麻酔','ますい','마취','手術・処置の際に薬を用いて痛みや感覚、場合によっては意識を一時的に失わせること。','手術は全身麻酔で行われ、数時間後に意識が戻った。','수술은 전신마취로 진행되었고 몇 시간 뒤 의식이 돌아왔다.'),
('n1-1642','2026-10-29','畜産','ちくさん','축산','牛・豚・鶏などの家畜を飼育し、肉・乳・卵などを生産する産業。','飼料価格の高騰が畜産農家の経営を圧迫している。','사료 가격 급등이 축산 농가의 경영을 압박하고 있다.'),
('n1-1646','2026-10-29','勤労','きんろう','근로; 노동','仕事に励み、働くこと。','勤労によって得た所得には一定の条件で税が課される。','근로로 얻은 소득에는 일정 조건에서 세금이 부과된다.'),
('n1-1647','2026-10-29','物議','ぶつぎ','물의; 논란','世間で多くの人が問題として取り上げ、議論すること。','その発言は誤解を招き、社内外で物議を醸した。','그 발언은 오해를 불러 회사 안팎에서 논란을 일으켰다.'),
('n1-1650','2026-10-29','旅券','りょけん','여권; 패스포트','外国へ渡航する人の身分・国籍を公的に証明する文書。','海外出張の前に旅券の有効期限を確認しておいた。','해외 출장 전에 여권 유효기간을 확인해 두었다.'),
('n1-1651','2026-10-29','慣行','かんこう','관행','社会・組織などで長く繰り返され、習慣として定着したやり方。','昔からの慣行でも、合理性がなければ見直す必要がある。','오래된 관행이라도 합리성이 없다면 재검토할 필요가 있다.'),
('n1-1662','2026-10-29','脱退','だったい','탈퇴','所属していた組織・団体から離れ、構成員でなくなること。','加盟条件の変更を受け、団体から脱退する企業も出てきた。','가입 조건 변경으로 단체에서 탈퇴하는 기업도 생겼다.'),
('n1-1664','2026-10-29','感慨','かんがい','감개; 깊은 감회','過去や経験を思い返したときに心に深くわき起こる思い。','十年かけた事業が完成し、担当者は深い感慨に浸った。','10년에 걸친 사업이 완성되어 담당자는 깊은 감회에 잠겼다.'),
('n1-1669','2026-10-29','回覧','かいらん','회람; 돌려봄','文書・資料などを順番に回して、複数の人が見ること。','会議資料を部署内で回覧し、全員の確認を取った。','회의 자료를 부서 내에서 회람해 전원의 확인을 받았다.'),
('n1-1670','2026-10-29','年鑑','ねんかん','연감','ある分野の一年間の出来事・統計・資料などをまとめ、年ごとに刊行する資料。','業界年鑑を使って市場規模の推移を調べた。','업계 연감을 이용해 시장 규모 추이를 조사했다.'),
('n1-1691','2026-10-29','錯覚','さっかく','착각; 잘못된 지각','実際とは異なるように感じたり、事実を誤って認識したりすること。','照明の影響で、部屋が実際より広いと錯覚した。','조명 영향으로 방이 실제보다 넓다고 착각했다.'),
('n1-1700','2026-10-29','採掘','さいくつ','채굴','地下・海底などから鉱石・資源を掘り出すこと。','資源の採掘には環境への影響を抑える対策が必要だ。','자원 채굴에는 환경 영향을 줄이기 위한 대책이 필요하다.'),
('n1-1708','2026-10-29','失格','しっかく','실격; 자격 상실','規則違反・基準未達などによって資格を失うこと。','規定時間を超えたため、その選手は失格となった。','규정 시간을 초과해 그 선수는 실격 처리됐다.'),
('n1-1715','2026-10-29','束縛','そくばく','속박; 구속','行動・考えなどの自由を制限し、自由にできないようにすること。','細かな規則で社員を過度に束縛すると、自主性が失われる。','세세한 규칙으로 직원을 지나치게 속박하면 자율성이 사라진다.'),
('n1-1771','2026-10-29','即ち','すなわち','즉; 다시 말해','前の内容を言い換えたり、その内容から導かれる結論を示したりするときに用いる。','この制度の対象は常勤社員、すなわち週五日勤務を原則とする社員である。','이 제도의 대상은 상근 사원, 즉 주 5일 근무를 원칙으로 하는 사원이다.'),
('n1-1789','2026-10-30','果て','はて','끝; 끝자락; 종말','物事・場所・時間などの最終の所。行き着く先。','長い交渉の果てに、双方はようやく合意に達した。','긴 협상의 끝에 양측은 마침내 합의에 도달했다.'),
('n1-1803','2026-10-30','策','さく','책; 방책; 대책; 전략','目的を達成したり問題を解決したりするための方法・手段・計画。','人手不足を解消するには、採用だけでなく業務を減らす策も必要だ。','인력 부족을 해소하려면 채용뿐 아니라 업무를 줄이는 방책도 필요하다.'),
('n1-1833','2026-10-30','領地','りょうち','영지; 지배 지역','領主などが支配・所有する土地。特に封建社会の支配地域をいう。','中世には領主同士が領地をめぐって争うことも少なくなかった。','중세에는 영주끼리 영지를 둘러싸고 다투는 일도 적지 않았다.'),
('n1-1843','2026-10-30','志','こころざし','뜻; 포부; 의지','将来成し遂げようと心に決めた目標・意志。','同じ志を持つ仲間が集まり、地域の教育を支援する団体を立ち上げた。','같은 뜻을 가진 사람들이 모여 지역 교육을 지원하는 단체를 만들었다.'),
('n1-1852','2026-10-30','不動産','ふどうさん','부동산','土地や建物など、移動させることのできない財産。','駅周辺の再開発に伴って、不動産価格が大きく上昇した。','역 주변 재개발에 따라 부동산 가격이 크게 상승했다.'),
('n1-1878','2026-10-30','富','とみ','부; 재산; 풍요','多くの財産や資源を持っていること。また、その財産・豊かさ。','天然資源だけでなく、人材や技術も国の重要な富だと考えられている。','천연자원뿐 아니라 인재와 기술도 국가의 중요한 부라고 여겨진다.'),
('n1-1890','2026-10-30','枠','わく','틀; 테두리; 범위; 한도','物の周囲を囲む縁・フレーム。また、制度・予算・人数などについて定められた範囲・限度。','今年度は採用枠を広げ、より多様な人材を受け入れる方針だ。','올해는 채용 인원을 늘려 더욱 다양한 인재를 받아들일 방침이다.'),
('n1-1892','2026-10-30','軸','じく','축; 중심축; 중심이 되는 기준','回転する物の中心となる棒。また、物事を成り立たせる中心・基準。','顧客の利便性を軸に、サービス全体の設計を見直した。','고객 편의성을 중심축으로 서비스 전체 설계를 재검토했다.'),
('n1-1893','2026-10-30','インフレ','インフレ','인플레이션; 물가의 지속적 상승','物価が継続的に上昇し、相対的に貨幣の価値が下がる経済現象。インフレーション。','急速なインフレによって生活必需品の価格が大きく上昇した。','급격한 인플레이션으로 생활필수품 가격이 크게 올랐다.'),
('n1-1905','2026-10-30','邸宅','ていたく','저택; 규모가 큰 주택','広い敷地を持つ、規模が大きく立派な住宅。','かつて実業家が暮らしていた邸宅が、現在は記念館として公開されている。','과거 사업가가 살던 저택이 현재는 기념관으로 공개되어 있다.'),
('n1-1916','2026-10-30','切っ掛け','きっかけ','계기; 기회; 발단','ある行動・変化・出来事が始まる原因や機会となるもの。','留学をきっかけに、自分の将来について真剣に考えるようになった。','유학을 계기로 자신의 장래에 대해 진지하게 생각하게 되었다.'),
('n1-1922','2026-10-30','核','かく','핵; 중심; 핵심','物事の中心となる部分。また、原子核・細胞核などのように、中心部を構成するもの。','この技術は今後の事業戦略の核になると期待されている。','이 기술은 향후 사업 전략의 핵심이 될 것으로 기대되고 있다.'),
('n1-1964','2026-10-30','闇','やみ','어둠; 암흑; 불법·은밀한 영역','光がなく暗いこと。また、表に出ない不正・違法な領域。','事件の背後には、まだ深い闇が残されている。','사건의 배후에는 아직 깊은 어둠이 남아 있다.'),
('n1-1966','2026-10-30','刑','けい','형벌; 형','法律に基づいて犯罪者に科される罰。','裁判所は被告に重い刑を言い渡した。','법원은 피고인에게 무거운 형을 선고했다.'),
('n1-1976','2026-10-30','返還','へんかん','반환; 돌려줌','借りていた物・土地・権利などを元の持ち主へ返すこと。','契約終了後、借りていた機器を会社に返還した。','계약 종료 후 빌렸던 장비를 회사에 반환했다.'),
('n1-1977','2026-10-30','自惚れ','うぬぼれ','자만; 자만심; 우쭐함','自分の能力・容姿などを実際以上に高く評価して得意になること。','少し褒められただけで自惚れてはいけない。','조금 칭찬받았다고 자만해서는 안 된다.'),
('n1-1996','2026-10-30','学士','がくし','학사; 학사 학위','大学の学部を卒業した者に授与される学位。また、その取得者。','大学を卒業し、工学の学士号を取得した。','대학을 졸업하고 공학 학사 학위를 취득했다.'),
('n1-2049','2026-10-30','興業','こうぎょう','사업 진흥; 산업 사업; 흥업','事業・産業を起こし、盛んにすること。','政府は地域の興業を支援するため新制度を設けた。','정부는 지역 산업 진흥을 지원하기 위해 새 제도를 마련했다.'),
('n1-2056','2026-10-30','ストライキ','ストライキ','파업; 스트라이크','労働者が要求を実現するため集団で仕事を停止すること。','賃金交渉が決裂し、労働組合はストライキに入った。','임금 협상이 결렬되어 노동조합은 파업에 들어갔다.'),
('n1-2090','2026-10-30','玄人','くろうと','전문가; 프로; 숙련자','ある分野に熟達した専門家・職業人。','玄人が見ても完成度の高い作品だ。','전문가가 봐도 완성도가 높은 작품이다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2094','2026-10-31','合議','ごうぎ','합의; 협의; 여러 사람이 의논함','複数の人が集まって相談し、意見をまとめること。','重要な案件は委員全員の合議で決める。','중요한 안건은 위원 전원의 협의로 결정한다.'),
('n1-2106','2026-10-31','参議院','さんぎいん','참의원; 일본 국회의 상원','日本の国会を構成する二つの議院の一つ。','法案は参議院でも審議される。','법안은 참의원에서도 심의된다.'),
('n1-2121','2026-10-31','衆議院','しゅうぎいん','중의원; 일본 국회의 하원','日本の国会を構成する二つの議院の一つ。','予算案は衆議院で審議された。','예산안은 중의원에서 심의되었다.'),
('n1-2207','2026-10-31','兼業','けんぎょう','겸업; 부업 겸함','本業のほかに別の仕事・事業も行うこと。','会社の規定で兼業が認められている。','회사 규정상 겸업이 허용되어 있다.'),
('n1-2229','2026-10-31','標語','ひょうご','표어; 슬로건','主張・目標などを短く分かりやすく表した言葉。','交通安全の標語を募集している。','교통안전 표어를 모집하고 있다.'),
('n1-2233','2026-10-31','下調べ','したしらべ','사전 조사; 예비 조사','本格的に行う前に、必要な情報をあらかじめ調べること。','旅行前に交通手段を下調べしておいた。','여행 전에 교통수단을 미리 조사해 두었다.'),
('n1-2238','2026-10-31','年輪','ねんりん','나이테; 연륜','木の幹の断面に現れる一年ごとの輪。また、長年の経験の積み重ねを比喩的にいう。','切り株の年輪を数えて木の年齢を調べた。','그루터기의 나이테를 세어 나무의 나이를 알아봤다.'),
('n1-2239','2026-10-31','文化財','ぶんかざい','문화재','歴史・芸術・学術などの面で価値が高く、保存すべき文化的な財産。','この寺は国の重要文化財に指定されている。','이 절은 국가 중요문화재로 지정되어 있다.'),
('n1-2246','2026-10-31','雪崩','なだれ','눈사태','山に積もった雪が大量に崩れ落ちる現象。','大雪の後は雪崩に注意が必要だ。','폭설 뒤에는 눈사태에 주의해야 한다.'),
('n1-2278','2026-10-31','錯誤','さくご','착오; 잘못; 오류','認識・判断などを誤ること。また、その誤り。','手続き上の錯誤が原因で、申請が正しく処理されなかった。','절차상의 착오 때문에 신청이 제대로 처리되지 않았다.'),
('n1-2309','2026-10-31','酪農','らくのう','낙농; 젖소 등을 길러 유제품을 생산하는 산업','牛などを飼育し、乳や乳製品を生産する農業。','北海道では酪農が盛んな地域が多い。','홋카이도에는 낙농이 활발한 지역이 많다.'),
('n1-2313','2026-10-31','埋蔵','まいぞう','매장; 땅속에 묻혀 있음; 매장되어 보존됨','地下などに埋めて保存すること。また、地下に資源・遺物などが存在すること。','この地域には豊富な天然資源が埋蔵されている。','이 지역에는 풍부한 천연자원이 매장되어 있다.'),
('n1-2315','2026-10-31','領海','りょうかい','영해','沿岸国の主権が及ぶ、海岸から一定範囲の海域。','外国船が領海に入ったことが確認された。','외국 선박이 영해에 들어온 것이 확인됐다.'),
('n1-2321','2026-10-31','余暇','よか','여가; 자유 시간','仕事・学業などから離れて自由に使える時間。','余暇を利用して資格の勉強を始めた。','여가 시간을 이용해 자격증 공부를 시작했다.'),
('n1-2329','2026-10-31','不評','ふひょう','악평; 평판이 나쁨; 인기 없음','評判・評価が悪いこと。人々に好まれていないこと。','新しい料金制度は利用者から不評だった。','새로운 요금 제도는 이용자들에게 평판이 좋지 않았다.'),
('n1-2333','2026-10-31','実費','じっぴ','실비; 실제로 든 비용','実際に必要となった費用。','交通費は会社が実費で精算してくれる。','교통비는 회사가 실제로 든 비용만큼 정산해 준다.'),
('n1-2345','2026-10-31','聴講','ちょうこう','청강; 강의를 들음','講義・講演などを聴くこと。特に、正規の履修者でなく授業を聴くこと。','興味のある教授の講義を聴講することにした。','관심 있는 교수의 강의를 청강하기로 했다.'),
('n1-2354','2026-10-31','混血','こんけつ','혼혈; 서로 다른 계통의 혈통이 섞임','異なる人種・民族的背景などを持つ親の血統が混じること。また、その出自を指す語。','古い資料では『混血』という表現が使われていることがある。','오래된 자료에서는 ''혼혈''이라는 표현이 사용되는 경우가 있다.'),
('n1-2391','2026-10-31','好況','こうきょう','호황; 경기 호조','経済・商売などの状態が良く、活発なこと。','輸出産業は好況が続いている。','수출 산업은 호황이 계속되고 있다.'),
('n1-2404','2026-10-31','海抜','かいばつ','해발; 해수면 기준 높이','平均海面を基準に測った陸地の高さ。','この町は海抜千メートル以上の場所にある。','이 마을은 해발 1,000미터가 넘는 곳에 있다.'),
('n1-2436','2026-11-01','公','おおやけ','공적임; 공공; 공식적인 것','個人ではなく、国家・社会・公共に関わること。また、広く知られること。','その事実はまだ公にはされていない。','그 사실은 아직 공식적으로 공개되지 않았다.'),
('n1-2460','2026-11-01','隠居','いんきょ','은퇴; 은거; 은퇴한 사람','仕事や家業などの第一線から退いて静かに暮らすこと。また、その人。','祖父は店を息子に任せて隠居した。','할아버지는 가게를 아들에게 맡기고 은퇴했다.'),
('n1-2468','2026-11-01','保障','ほしょう','보장; 보호','権利・安全・生活などが損なわれないよう守ること。','憲法は国民の基本的人権を保障している。','헌법은 국민의 기본적 인권을 보장하고 있다.'),
('n1-2470','2026-11-01','構え','かまえ','자세; 태세; 구조; 외관','物事に対応する姿勢や身構え。また、建物などの造り・外観。','相手の攻撃に備えて構えを取った。','상대의 공격에 대비해 자세를 취했다.'),
('n1-2506','2026-11-01','躾','しつけ','예절 교육; 훈육; 가정교육','子どもなどに礼儀・生活習慣・社会的な作法を身につけさせること。','家庭での躾は子どもの生活習慣に大きく影響する。','가정에서의 훈육은 아이의 생활 습관에 큰 영향을 준다.'),
('n1-2521','2026-11-01','お世辞','おせじ','빈말; 아첨; 듣기 좋은 말','相手の機嫌を取るために言う、実際の気持ち以上に褒める言葉。','お世辞ではなく、本当に素晴らしい作品だと思う。','빈말이 아니라 정말 훌륭한 작품이라고 생각한다.'),
('n1-2527','2026-11-01','茶の湯','ちゃのゆ','다도; 일본식 차 의식','抹茶を点てて客にふるまう、日本の伝統的な茶の作法・文化。茶道。','京都で茶の湯の作法を体験した。','교토에서 일본 다도의 예법을 체험했다.'),
('n1-2528','2026-11-01','係り','かかり','담당자; 담당; 맡은 사람','特定の仕事・役目を受け持つ人。また、その担当。','受付の係りに会場までの道を尋ねた。','접수 담당자에게 행사장까지 가는 길을 물었다.'),
('n1-2562','2026-11-01','実業家','じつぎょうか','실업가; 기업가; 사업가','商工業・金融業などの事業を経営する人。','彼は若くして成功した実業家として知られている。','그는 젊은 나이에 성공한 기업가로 알려져 있다.'),
('n1-2566','2026-11-01','結び付き','むすびつき','연결; 관계; 결부','物事どうしのつながり・関係。','地域社会との結び付きが強い会社だ。','지역사회와의 연계가 강한 회사다.'),
('n1-2577','2026-11-01','効き目','ききめ','효과; 효험; 약효','薬・方法などによって現れる効果。','この薬はすぐに効き目が現れた。','이 약은 곧 효과가 나타났다.'),
('n1-2581','2026-11-01','跡継ぎ','あとつぎ','후계자; 대를 이을 사람','家業・地位・財産などを引き継ぐ人。','会社の跡継ぎを誰にするか話し合った。','회사의 후계자를 누구로 할지 논의했다.'),
('n1-2603','2026-11-01','フィルター','フィルター','필터; 여과 장치','不要なものを取り除くために通過させる装置。また、写真・映像などの効果用具。','エアコンのフィルターを掃除した。','에어컨 필터를 청소했다.'),
('n1-2702','2026-11-01','ボイコット','ボイコット','보이콧; 집단 거부','抗議などの目的で、参加・購入・取引などを集団で拒否すること。','選手たちは大会をボイコットすると発表した。','선수들은 대회를 보이콧하겠다고 발표했다.'),
('n1-2714','2026-11-01','多数決','たすうけつ','다수결','多数の意見に従って決定する方法。','最終案は多数決で決めることになった。','최종안은 다수결로 결정하기로 했다.'),
('n1-2732','2026-11-01','橋渡し','はしわたし','가교; 중개; 연결 역할','二者の間を取り持ち、関係をつなぐこと。','通訳が両国の橋渡し役を務めた。','통역사가 양국의 가교 역할을 맡았다.'),
('n1-2748','2026-11-01','議事堂','ぎじどう','의사당; 국회의사당','議会が開かれる建物。','観光で国会議事堂を見学した。','관광으로 국회의사당을 견학했다.'),
('n1-2814','2026-11-01','封建','ほうけん','봉건; 봉건제','土地を基盤に主従関係を結ぶ封建制度。また、その性質。','中世社会では封建制度が広く見られた。','중세 사회에서는 봉건 제도가 널리 나타났다.'),
('n1-2828','2026-11-01','縁','えん','인연; 관계; 연고','人・物事を結び付ける関係や巡り合わせ。','不思議な縁で今の会社に入ることになった。','묘한 인연으로 지금 회사에 들어가게 됐다.'),
('n1-2883','2026-11-01','座談会','ざだんかい','좌담회; 원탁 토론','数人が集まり、自由に意見を交わす会。','専門家を招いて座談会を開いた。','전문가를 초청해 좌담회를 열었다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2925','2026-11-02','にも拘らず','にもかかわらず','~에도 불구하고','前の事柄から予想される結果と反対であることを示す。','雨にもかかわらず多くの人が集まった。','비가 왔음에도 불구하고 많은 사람이 모였다.'),
('n1-2963','2026-11-02','濫用','らんよう','남용; 오용','権利・薬物・言葉などを必要以上または不適切に使うこと。','権限を濫用してはいけない。','권한을 남용해서는 안 된다.'),
('n1-2968','2026-11-02','伝来','でんらい','전래; 전해 내려옴','外国などから伝わって来ること。また、代々受け継がれて伝わること。','仏教は大陸から日本へ伝来した。','불교는 대륙에서 일본으로 전래되었다.'),
('n1-2976','2026-11-02','統率','とうそつ','통솔; 지휘','集団をまとめ、率いること。','監督はチームを見事に統率した。','감독은 팀을 훌륭하게 통솔했다.'),
('n1-2978','2026-11-02','産出','さんしゅつ','산출; 생산; 산출량','物資などを生産すること。また、その産物や産出量。','この地域では良質な石炭を産出する。','이 지역에서는 양질의 석탄을 산출한다.'),
('n1-2982','2026-11-02','照合','しょうごう','대조; 조회; 대조 확인','二つ以上の資料・情報などを照らし合わせて確かめること。','申請書の内容を本人確認書類と照合した。','신청서 내용을 본인 확인 서류와 대조했다.'),
('n1-0637','2026-11-02','密接','みっせつ','밀접; 긴밀함','関係が非常に深く、強く結びついているさま。','人口構成の変化は、地域の医療需要と密接に関係している。','인구 구성의 변화는 지역의 의료 수요와 밀접하게 관련되어 있다.'),
('n1-0698','2026-11-02','強硬','きょうこう','강경; 타협하지 않는 태도','主張・態度などが非常に強く、妥協・譲歩をしないさま。','相手側が強硬な姿勢を崩さず、交渉は再び中断した。','상대 측이 강경한 태도를 굽히지 않아 협상은 다시 중단됐다.'),
('n1-0408','2026-11-02','物資','ぶっし','물자; 물품','生活・活動・生産・救援などに必要となる物品や材料。','道路が寸断されたため、被災地への救援物資はヘリコプターで運ばれた。','도로가 끊겨 재해 지역으로의 구호 물자는 헬리콥터로 운반되었다.'),
('n1-0410','2026-11-02','所持','しょじ','소지; 보유','物品・資格・証明書などを自分のものとして持っていること。','入場時には身分証明書を所持しているか確認される場合がある。','입장 시에는 신분증을 소지하고 있는지 확인받을 수 있다.'),
('n1-0411','2026-11-02','再現','さいげん','재현; 다시 나타냄','過去の出来事・状態・現象などを、もう一度同じように現すこと。また、再び現れること。','不具合を修正するには、まず同じ現象をテスト環境で再現する必要がある。','오류를 수정하려면 먼저 같은 현상을 테스트 환경에서 재현할 필요가 있다.'),
('n1-0416','2026-11-02','出世','しゅっせ','출세; 승진하여 높은 지위에 오름','社会や組織の中で地位が上がり、成功して名声や高い立場を得ること。','出世だけを目標にするより、自分が納得できる仕事を続けたいと考える人も増えている。','출세만을 목표로 하기보다 자신이 납득할 수 있는 일을 계속하고 싶다고 생각하는 사람도 늘고 있다.'),
('n1-0418','2026-11-02','中断','ちゅうだん','중단; 일시 정지','続いていた作業・計画・活動などを途中で止めること。後で再開する場合にも用いる。','激しい雨のため試合は一時中断されたが、天候の回復後に再開した。','폭우 때문에 경기는 일시 중단되었지만 날씨가 회복된 뒤 재개되었다.'),
('n1-0421','2026-11-02','中継','ちゅうけい','중계; 중간에서 이어 줌','離れた場所や装置などの間に入って情報・放送・通信などをつなぐこと。また、現場から放送すること。','決勝戦は現地から全国へ生中継され、多くの人がテレビで観戦した。','결승전은 현지에서 전국으로 생중계되어 많은 사람이 TV로 관전했다.'),
('n1-0425','2026-11-02','手順','てじゅん','절차; 순서; 작업 순서','物事を行う際に従うべき順序・方法・段階。','作業手順を省略すると重大な事故につながるため、必ずマニュアルどおりに進めてください。','작업 절차를 생략하면 중대한 사고로 이어질 수 있으므로 반드시 매뉴얼대로 진행해 주세요.'),
('n1-0426','2026-11-02','連盟','れんめい','연맹; 연합 조직','共通の目的を持つ複数の団体・組織・国家などが結び付いて作る組織。','各国の競技団体をまとめる国際連盟が、新しい大会規則を発表した。','각국의 경기 단체를 아우르는 국제 연맹이 새로운 대회 규정을 발표했다.'),
('n1-0432','2026-11-02','気配','きはい','기미; 기색; 낌새; 조짐','人や物がそこにいるように感じられる様子。また、何かが起こりそうだと感じさせる兆し。市場の動きを指す用法もある。','雨は止んだものの、空が暗く、まだ天候が回復する気配はない。','비는 그쳤지만 하늘이 어두워 아직 날씨가 회복될 기미는 없다.'),
('n1-0433','2026-11-02','経路','けいろ','경로; 루트; 통로','目的地まで通る道筋。また、物・情報・感染などが伝わる道筋や過程。','不正アクセスがどの経路から行われたのか、通信ログを使って調査している。','부정 접근이 어떤 경로를 통해 이루어졌는지 통신 로그로 조사하고 있다.'),
('n1-0438','2026-11-02','救済','きゅうさい','구제; 구원; 어려움에서 도움','困難・被害・貧困などに苦しむ人を助け、救うこと。法律上の権利を守るための措置にも用いる。','制度の対象から漏れた人を救済するため、追加の支援策が設けられた。','제도 대상에서 빠진 사람을 구제하기 위해 추가 지원책이 마련되었다.'),
('n1-0439','2026-11-02','独裁','どくさい','독재; 권력 독점','一人または少数の集団が政治的・組織的な権力を集中して握り、他の意見を十分に認めず支配すること。','権力が一人に集中しすぎると、組織運営が独裁的になる危険がある。','권력이 한 사람에게 지나치게 집중되면 조직 운영이 독재적으로 변할 위험이 있다.'),
('n1-0440','2026-11-03','到達','とうたつ','도달; 도착; 일정 수준에 이름','目的地・目標・一定の水準などにたどり着くこと。','研究チームは十年かけて、ようやく実用化できる水準に到達した。','연구팀은 10년에 걸쳐 마침내 실용화할 수 있는 수준에 도달했다.'),
('n1-0441','2026-11-03','動向','どうこう','동향; 움직임; 추세','社会・市場・人々の考えや行動などが、今後どの方向へ動いていくかという傾向。','市場の動向を見ながら、来年度の投資額を慎重に決める必要がある。','시장의 동향을 보면서 내년도 투자액을 신중하게 결정할 필요가 있다.'),
('n1-0448','2026-11-03','暴動','ぼうどう','폭동; 집단 소요','多数の人が集団で暴力的な行動を起こし、社会秩序を乱すこと。','抗議活動の一部が暴動に発展し、商店や公共施設に被害が出た。','항의 활동 일부가 폭동으로 번져 상점과 공공시설에 피해가 발생했다.'),
('n1-0450','2026-11-03','後退','こうたい','후퇴; 퇴보; 뒤로 물러남','位置が後ろへ下がること。また、状態・水準・勢いなどが以前より悪くなること。','制度改正によって利用者の権利が後退することがないよう、慎重な議論が必要だ。','제도 개정으로 이용자의 권리가 후퇴하지 않도록 신중한 논의가 필요하다.'),
('n1-0451','2026-11-03','育成','いくせい','육성; 양성','人材・産業・文化などが成長するよう、計画的に育てること。','将来のリーダーを育成するため、若手社員向けの研修制度を見直した。','미래의 리더를 육성하기 위해 젊은 직원 대상 연수 제도를 재검토했다.'),
('n1-0455','2026-11-03','役職','やくしょく','직책; 직위','組織の中で責任や権限を伴う職務上の地位・肩書。','役職が上がるほど、専門知識だけでなく組織全体を見る力も求められる。','직책이 높아질수록 전문 지식뿐 아니라 조직 전체를 보는 능력도 요구된다.'),
('n1-0457','2026-11-03','事柄','ことがら','사항; 일; 사안','話題・判断・説明などの対象となる、ある具体的な物事や内容。','契約に関する重要な事柄は、口頭だけでなく必ず文書に残したほうがよい。','계약과 관련된 중요한 사항은 구두뿐 아니라 반드시 문서로 남기는 편이 좋다.'),
('n1-0459','2026-11-03','義理','ぎり','의리; 사회적 도리; 인간관계상의 의무','人間関係や社会生活の中で、立場上果たすべき道理・付き合い・恩に応える責任。','義理だけで参加した会だったが、思いがけず有益な人脈ができた。','의리 때문에 참석한 모임이었지만 뜻밖에 유익한 인맥이 생겼다.'),
('n1-0465','2026-11-03','手元','てもと','손이 닿는 곳; 수중; 바로 곁','手の近く。また、自分が現在持っている物・金・資料などがあるところ。','本人確認に必要なので、手元に身分証明書を用意してから手続きを始めてください。','본인 확인에 필요하므로 신분증을 손에 준비한 뒤 절차를 시작해 주세요.'),
('n1-0468','2026-11-03','自覚','じかく','자각; 스스로 깨달음','自分の立場・責任・性質・能力などを自分自身で認識すること。','管理職になった以上、組織への影響力が大きいことを自覚して発言すべきだ。','관리직이 된 이상 조직에 미치는 영향력이 크다는 점을 자각하고 발언해야 한다.'),
('n1-0469','2026-11-03','倒産','とうさん','도산; 기업 파산','企業が資金不足などによって事業を続けられなくなり、経営が破綻すること。','原材料費の上昇と売上減少が重なり、老舗企業が倒産に追い込まれた。','원재료비 상승과 매출 감소가 겹쳐 오래된 기업이 도산에 몰렸다.'),
('n1-0477','2026-11-03','特許','とっきょ','특허; 특허권','新しい発明について、一定期間その発明を独占的に利用できる権利を国が認める制度。また、その権利。','新技術について特許を取得し、競合企業による無断利用を防ぐ。','신기술에 대해 특허를 취득해 경쟁 기업의 무단 이용을 막는다.'),
('n1-0478','2026-11-03','君主','くんしゅ','군주; 왕이나 황제','王・皇帝など、君主制の国家で原則として国家の元首となる人物。','立憲君主制では、君主の権限が憲法によって制限されている。','입헌군주제에서는 군주의 권한이 헌법에 의해 제한되어 있다.'),
('n1-0479','2026-11-03','野心','やしん','야심; 큰 목표를 이루려는 욕망','大きな成功・地位・権力などを得ようとする強い望み。文脈によって肯定的にも否定的にも使う。','世界市場で首位を目指すという野心的な計画を経営陣が発表した。','세계 시장에서 1위를 목표로 한다는 야심 찬 계획을 경영진이 발표했다.'),
('n1-0484','2026-11-03','現行','げんこう','현행; 현재 시행 중인 것','現在実施・使用されている制度・規則・方式など。','現行制度では対象外となる人が多いため、条件の見直しが検討されている。','현행 제도에서는 대상에서 제외되는 사람이 많아 조건 재검토가 검토되고 있다.'),
('n1-0488','2026-11-03','獲物','えもの','사냥감; 획득한 먹잇감; 노리는 대상','狩猟や捕食によって捕らえる動物・魚など。また、比喩的に狙いを定めた対象。','猛禽類は上空から獲物を見つけると、急降下して捕らえる。','맹금류는 상공에서 사냥감을 발견하면 급강하해 붙잡는다.'),
('n1-0490','2026-11-03','名簿','めいぼ','명부; 명단','組織・参加者・関係者などの氏名や連絡先をまとめた一覧・帳簿。','参加者名簿には個人情報が含まれるため、閲覧できる人を限定している。','참가자 명부에는 개인정보가 포함되어 있어 열람 가능한 사람을 제한하고 있다.'),
('n1-0494','2026-11-03','視野','しや','시야; 사고의 범위','目で見ることのできる範囲。また、物事を理解・判断するときに考慮できる範囲。','一つの専門分野だけでなく、関連分野も学ぶことで視野が広がった。','한 전문 분야뿐 아니라 관련 분야도 배우면서 시야가 넓어졌다.'),
('n1-0495','2026-11-03','酸化','さんか','산화','物質が酸素と結び付くなどして電子を失う化学反応。日常では金属がさびたり食品の品質が変化したりする現象にもいう。','切ったリンゴは空気に触れると酸化し、表面が茶色くなりやすい。','자른 사과는 공기에 닿으면 산화되어 표면이 갈색으로 변하기 쉽다.'),
('n1-0496','2026-11-03','幹線','かんせん','간선; 주요 노선','鉄道・道路・通信網などで、全体の中心となる主要な路線・系統。','幹線道路が事故で通行止めになり、周辺の一般道が大渋滞した。','간선도로가 사고로 통행금지되어 주변 일반도로가 크게 정체되었다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0497','2026-11-04','判定','はんてい','판정; 판단하여 결정함','基準に照らして、結果・優劣・適否・真偽などを判断し決定すること。','画像だけでは判定できない場合、専門家が実物を確認する。','이미지만으로 판정할 수 없는 경우 전문가가 실물을 확인한다.'),
('n1-0499','2026-11-04','自主','じしゅ','자주; 자발적으로 결정함','他から命令・強制されるのではなく、自分たちの判断と責任で行動すること。','学校は生徒の自主性を尊重し、行事の企画をできるだけ生徒に任せている。','학교는 학생의 자주성을 존중해 행사의 기획을 가능한 한 학생에게 맡기고 있다.'),
('n1-0504','2026-11-04','対決','たいけつ','대결; 정면 승부','互いに向き合い、勝敗・優劣・主張の決着をつけようと争うこと。','決勝では長年のライバル同士が再び対決することになった。','결승에서는 오랜 라이벌끼리 다시 대결하게 되었다.'),
('n1-0506','2026-11-04','異議','いぎ','이의; 반대 의견','決定・主張・処分などに対して示す、異なる意見や反対の意思。','審査結果に異議がある場合は、期限内に書面で申し立てることができる。','심사 결과에 이의가 있는 경우 기한 내에 서면으로 이의를 제기할 수 있다.'),
('n1-0507','2026-11-04','国防','こくぼう','국방; 국가 방위','他国からの侵攻・脅威などに備えて国家の安全・領土・国民を守ること。','国防に必要な費用と社会保障への支出をどう両立させるかが議論されている。','국방에 필요한 비용과 사회보장 지출을 어떻게 양립시킬지가 논의되고 있다.'),
('n1-0510','2026-11-04','偽造','ぎぞう','위조; 가짜를 진짜처럼 만듦','文書・貨幣・証明書・商品などを、本物であるかのように不正に作ること。','身分証明書を偽造して他人になりすました疑いで男が逮捕された。','신분증을 위조해 다른 사람으로 가장한 혐의로 남성이 체포되었다.'),
('n1-0513','2026-11-04','動揺','どうよう','동요; 흔들림; 평정심을 잃음','物が揺れ動くこと。また、予想外の出来事などで心や社会の状態が不安定になること。','突然の発表に社員は動揺したが、責任者の説明を聞いて次第に落ち着いた。','갑작스러운 발표에 직원들은 동요했지만 책임자의 설명을 듣고 점차 진정했다.'),
('n1-0516','2026-11-04','決議','けつぎ','결의; 회의에서 의결함','会議・議会などで提案について討議し、参加者の意思として正式に決定すること。また、その決定。','総会では経営体制の見直しを求める決議が賛成多数で採択された。','총회에서는 경영 체제 재검토를 요구하는 결의가 찬성 다수로 채택되었다.'),
('n1-0523','2026-11-04','伝達','でんたつ','전달; 전달함','情報・命令・意思・刺激などを、相手や別の場所へ伝えること。','緊急時には情報伝達の経路を一本化し、誤った指示が広がらないようにする。','긴급 시에는 정보 전달 경로를 일원화해 잘못된 지시가 퍼지지 않게 한다.'),
('n1-0524','2026-11-04','産物','さんぶつ','산물; 생산물; 결과물','ある地域で生産される物。また、ある原因・時代・活動などから生まれた結果を比喩的にいう。','この制度は当時の社会状況の産物であり、現在の事情には合わない部分もある。','이 제도는 당시 사회 상황의 산물이라 현재 사정에는 맞지 않는 부분도 있다.'),
('n1-0534','2026-11-04','自立','じりつ','자립; 스스로 생활함','他人の支配・援助に過度に頼らず、自分の力と責任で生活・行動すること。','若者の経済的な自立を支援するため、職業訓練の制度が拡充された。','청년의 경제적 자립을 지원하기 위해 직업훈련 제도가 확대되었다.'),
('n1-0539','2026-11-04','変革','へんかく','변혁; 근본적인 변화','制度・組織・社会などを、従来とは大きく異なる形へ根本的に変えること。','デジタル技術は単なる効率化ではなく、産業構造そのものの変革を促している。','디지털 기술은 단순한 효율화를 넘어 산업 구조 자체의 변혁을 촉진하고 있다.'),
('n1-0546','2026-11-04','主題','しゅだい','주제; 중심이 되는 문제','文章・作品・研究・議論などで中心となる題目や考え。','この小説の主題は、社会の変化の中で失われていく人間関係だ。','이 소설의 주제는 사회 변화 속에서 사라져 가는 인간관계이다.'),
('n1-0547','2026-11-04','小切手','こぎって','수표','銀行に対して、記載した金額を所持人などに支払うよう指図する有価証券。','高額の取引では、現金ではなく小切手で支払われることもある。','고액 거래에서는 현금이 아니라 수표로 지급되는 경우도 있다.'),
('n1-0549','2026-11-04','放出','ほうしゅつ','방출; 내보냄; 풀어냄','蓄えられていた物質・エネルギー・資金・在庫などを外へ出すこと。','政府は価格の急騰を抑えるため、備蓄していた在庫の一部を市場に放出した。','정부는 가격 급등을 억제하기 위해 비축 재고 일부를 시장에 방출했다.'),
('n1-0550','2026-11-04','処罰','しょばつ','처벌; 벌을 줌','法律・規則などに違反した者に対して、罰や制裁を科すこと。','規則に違反した職員をどのように処罰するかは、正式な手続きに沿って決められる。','규정을 위반한 직원을 어떻게 처벌할지는 정식 절차에 따라 결정된다.'),
('n1-0551','2026-11-04','人体','じんたい','인체; 사람의 몸','人間の身体。特に、生物学・医学などで対象として捉えた人の体。','この物質が人体に与える影響について、長期的な調査が続けられている。','이 물질이 인체에 미치는 영향에 대해 장기적인 조사가 계속되고 있다.'),
('n1-0552','2026-11-04','創立','そうりつ','창립; 기관·단체를 처음 세움','学校・会社・団体などの組織を新しく設立すること。','この大学は今年、創立百周年を迎え、記念式典が開かれた。','이 대학은 올해 창립 100주년을 맞아 기념식이 열렸다.'),
('n1-0554','2026-11-04','平行','へいこう','평행; 서로 만나지 않고 나란함','二つの直線や平面が、どこまで延ばしても交わらず一定の間隔を保つこと。','二本の道路はしばらく平行に走ったあと、山の手前で別の方向へ分かれる。','두 도로는 한동안 평행하게 이어지다가 산 앞에서 서로 다른 방향으로 갈라진다.'),
('n1-0556','2026-11-04','炭素','たんそ','탄소','元素の一つ。生物や有機物を構成する主要な元素で、元素記号はC。','企業には二酸化炭素の排出量を減らすための具体的な対策が求められている。','기업에는 이산화탄소 배출량을 줄이기 위한 구체적인 대책이 요구되고 있다.'),
('n1-0557','2026-11-05','返済','へんさい','상환; 빌린 돈이나 빚을 갚음','借りた金銭や借金を相手に返すこと。','住宅ローンは長期間にわたって返済するため、無理のない計画を立てる必要がある。','주택 대출은 장기간에 걸쳐 상환하므로 무리 없는 계획을 세울 필요가 있다.'),
('n1-0558','2026-11-05','総会','そうかい','총회; 전체 구성원이 모이는 회의','団体の構成員または代表者が広く集まり、重要事項を審議・決定する会議。','株主総会では新しい経営方針と役員人事について審議された。','주주총회에서는 새로운 경영 방침과 임원 인사에 대해 심의했다.'),
('n1-0559','2026-11-05','交付','こうふ','교부; 공적 문서·증서 등을 내줌','官公庁などが証明書・許可証・金銭などを正式に渡すこと。','申請内容に問題がなければ、約二週間後に許可証が交付される。','신청 내용에 문제가 없으면 약 2주 뒤 허가증이 교부된다.'),
('n1-0560','2026-11-05','基金','ききん','기금; 특정 목적을 위해 마련한 자금','特定の事業・活動・目的のために積み立て、運用する資金。','災害復興を支援する基金には、国内外から多くの寄付が寄せられた。','재해 복구를 지원하는 기금에는 국내외에서 많은 기부가 모였다.'),
('n1-0561','2026-11-05','着手','ちゃくしゅ','착수; 일을 시작함','仕事・計画・調査などに取りかかること。','予算が正式に承認され次第、新システムの開発に着手する予定だ。','예산이 정식 승인되는 대로 새 시스템 개발에 착수할 예정이다.'),
('n1-0563','2026-11-05','刊行','かんこう','간행; 출판하여 세상에 냄','書籍・雑誌・資料などを印刷・編集して出版すること。','研究成果をまとめた報告書が来月刊行される予定だ。','연구 성과를 정리한 보고서가 다음 달 간행될 예정이다.'),
('n1-0564','2026-11-05','対面','たいめん','대면; 직접 얼굴을 마주함','人と人が直接顔を合わせて会うこと。','重要な契約については、オンラインではなく対面で説明する方針になった。','중요한 계약은 온라인이 아니라 대면으로 설명하기로 했다.'),
('n1-0567','2026-11-05','配給','はいきゅう','배급; 정해진 기준에 따라 나누어 줌','食料・物資などを一定の基準に従って人々に割り当てて配ること。','災害直後は飲料水や食料の配給が限られ、長い列ができた。','재해 직후에는 식수와 식량 배급이 제한되어 긴 줄이 생겼다.'),
('n1-0571','2026-11-05','布告','ふこく','포고; 공식적으로 널리 알림','国・政府などが重要な決定や命令を公式に広く知らせること。また、その告示。','政府は非常事態を布告し、住民に不要不急の外出を控えるよう求めた。','정부는 비상사태를 포고하고 주민들에게 불필요한 외출을 자제해 달라고 요청했다.'),
('n1-0572','2026-11-05','生理','せいり','생리; 생리 기능; 월경','生物の体が生命を維持するために営む機能・作用。また、日常語では月経を指すことも多い。','睡眠不足は体の生理機能だけでなく、判断力にも影響を与える。','수면 부족은 신체의 생리 기능뿐 아니라 판단력에도 영향을 준다.'),
('n1-0574','2026-11-05','特集','とくしゅう','특집; 특정 주제를 집중적으로 다룸','新聞・雑誌・番組などで、特定のテーマを集中的に取り上げて構成すること。また、その記事・番組。','今月号では生成AIが働き方に与える影響を特集している。','이번 달 호에서는 생성형 AI가 일하는 방식에 미치는 영향을 특집으로 다루고 있다.'),
('n1-0576','2026-11-05','適応','てきおう','적응; 환경·조건에 맞게 변화함','環境・条件・状況などに合うように、自分の状態や行動を変えてなじむこと。','新しい勤務制度に適応するまで、部署ごとに一定の時間が必要だった。','새 근무 제도에 적응하기까지 부서마다 일정한 시간이 필요했다.'),
('n1-0577','2026-11-05','解剖','かいぼう','해부; 내부 구조를 조사함','生物の体を切り開いて内部の構造を調べること。転じて、物事を細かく分析する意味でも使う。','講義では模型と映像を使い、人体の構造を解剖学的に学ぶ。','강의에서는 모형과 영상을 사용해 인체 구조를 해부학적으로 배운다.'),
('n1-0578','2026-11-05','教訓','きょうくん','교훈; 경험에서 얻는 가르침','経験・失敗・出来事などから得られる、今後の行動の戒めや指針となる教え。','過去の事故から得た教訓を、今後の安全対策に生かさなければならない。','과거 사고에서 얻은 교훈을 앞으로의 안전 대책에 살려야 한다.'),
('n1-0580','2026-11-05','共感','きょうかん','공감; 상대의 감정·생각을 함께 느낌','他人の感情・考え・経験などを理解し、自分も同じように感じること。','彼の率直な体験談は、多くの若者から強い共感を集めた。','그의 솔직한 체험담은 많은 젊은이의 큰 공감을 얻었다.'),
('n1-0581','2026-11-05','育ち','そだち','성장; 자란 환경·배경','育つこと。また、どのような環境・土地・家庭などで育ったかという経歴。','彼は大阪生まれの東京育ちで、両方の地域に詳しい。','그는 오사카에서 태어나 도쿄에서 자라 두 지역 모두에 익숙하다.'),
('n1-0583','2026-11-05','一同','いちどう','일동; 한자리에 있는 모든 사람','ある集団・会合などに属する人々の全員。','社員一同、今回の受賞を心からうれしく思っています。','사원 일동은 이번 수상을 진심으로 기쁘게 생각하고 있습니다.'),
('n1-0584','2026-11-05','発足','はっそく','발족; 조직·제도가 새로 출범함','組織・制度・事業などが新しく成立し、活動を始めること。','専門家による第三者委員会が来月正式に発足する。','전문가로 구성된 제3자 위원회가 다음 달 정식으로 발족한다.'),
('n1-0588','2026-11-05','慣習','かんしゅう','관습; 오래 이어진 사회적 습관','ある社会・地域・集団で長い間繰り返され、一般に受け入れられてきた行動様式やならわし。','法律には書かれていなくても、長年の慣習として守られている決まりがある。','법에는 적혀 있지 않아도 오랜 관습으로 지켜지는 규칙이 있다.'),
('n1-0592','2026-11-05','打ち合わせ','うちあわせ','사전 협의; 업무 미팅; 사전 조율','仕事・行事・制作などを円滑に進めるため、関係者が事前に内容や手順を話し合うこと。','明日の顧客説明に備え、担当者同士で最終の打ち合わせを行った。','내일 고객 설명에 대비해 담당자끼리 최종 사전 협의를 했다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0595','2026-11-06','鉱山','こうざん','광산','地下・山地などから鉱石や鉱物資源を採掘する場所・事業所。','かつて栄えた鉱山の跡地は、現在では観光施設として公開されている。','한때 번성했던 광산 터는 현재 관광 시설로 공개되어 있다.'),
('n1-0598','2026-11-06','社交','しゃこう','사교; 사회적인 교제','社会生活の中で、人と付き合い交流すること。','彼女は社交の場でも自然に会話を広げられるので、人脈が広い。','그녀는 사교 자리에서도 자연스럽게 대화를 이어 갈 수 있어 인맥이 넓다.'),
('n1-0599','2026-11-06','中枢','ちゅうすう','중추; 핵심부; 중심 기능을 맡는 부분','組織・機関・神経系などで、中心となって重要な機能を担う部分。','首都には政治と行政の中枢を担う機関が集中している。','수도에는 정치와 행정의 중추를 담당하는 기관이 집중되어 있다.'),
('n1-0606','2026-11-06','風土','ふうど','풍토; 지역의 자연·생활 환경과 특성','ある土地の気候・地形・自然環境、およびそこから形成された生活・文化上の特徴。','地域の風土に合った建築様式が、長い年月をかけて発達してきた。','지역 풍토에 맞는 건축 양식이 오랜 세월에 걸쳐 발달해 왔다.'),
('n1-0607','2026-11-06','待ち合わせ','まちあわせ','약속 장소에서 만남; 만나기로 한 약속','時刻と場所をあらかじめ決め、そこで人と会うこと。また、その約束。','駅前は混雑するので、待ち合わせ場所を改札の外に変更した。','역 앞은 붐비므로 약속 장소를 개찰구 밖으로 바꿨다.'),
('n1-0608','2026-11-06','公認','こうにん','공인; 공식적으로 인정함','国・団体・社会などが、資格・立場・事実などを正式に認めること。','この大会で使用できるのは、競技団体が公認した用具に限られる。','이 대회에서 사용할 수 있는 것은 경기 단체가 공인한 장비로 한정된다.'),
('n1-0609','2026-11-06','検事','けんじ','검사; 형사 사건을 수사·기소하는 법률 공무원','犯罪を捜査し、必要に応じて被疑者を裁判所に起訴する権限をもつ司法官。','検事は証拠を精査したうえで、被疑者を起訴するかどうか判断した。','검사는 증거를 면밀히 검토한 뒤 피의자를 기소할지 판단했다.'),
('n1-0610','2026-11-06','風俗','ふうぞく','풍속; 사회의 생활 습관·풍습','ある時代・地域・社会に見られる、人々の生活上のならわしや習慣。','古い絵画は、当時の庶民の生活や風俗を知る貴重な資料になる。','옛 그림은 당시 서민의 생활과 풍속을 알 수 있는 귀중한 자료가 된다.'),
('n1-0614','2026-11-06','有機','ゆうき','유기; 생물·탄소 화합물과 관련됨; 유기적으로 연결됨','生物体・炭素化合物に関係すること。また、複数の部分が互いに密接に関連して全体を形づくること。','各部署の情報を有機的に結び付けることで、組織全体の判断を速くできる。','각 부서의 정보를 유기적으로 연결함으로써 조직 전체의 판단을 빠르게 할 수 있다.'),
('n1-0618','2026-11-06','比率','ひりつ','비율; 기준량에 대한 다른 양의 비','ある数量を基準となる数量と比較した割合。','売上に占める海外事業の比率が、この五年間で大きく上昇した。','매출에서 해외 사업이 차지하는 비율이 지난 5년간 크게 상승했다.'),
('n1-0619','2026-11-06','割り当て','わりあて','할당; 배정; 나누어 맡김','仕事・予算・数量・役割などを分け、それぞれの人や対象にあてること。また、その分。','担当者ごとの作業量を確認し、無理のないようにタスクの割り当てを調整した。','담당자별 작업량을 확인해 무리가 없도록 작업 할당을 조정했다.'),
('n1-0620','2026-11-06','褒美','ほうび','상; 포상; 잘한 일에 주는 보상','よい行い・成果・努力などをほめ、その報いとして与える金品や利益。','目標を達成した自分への褒美として、以前から欲しかった本を買った。','목표를 달성한 자신에게 주는 상으로 예전부터 갖고 싶었던 책을 샀다.'),
('n1-0621','2026-11-06','心得','こころえ','마음가짐; 알아두어야 할 사항; 기본 지식','物事を行う上で知っておくべき知識・心構え・注意点。','新任者には、業務上の心得と情報管理の基本を最初に説明する。','신임자에게는 업무상 알아두어야 할 사항과 정보 관리의 기본을 처음에 설명한다.'),
('n1-0622','2026-11-06','補給','ほきゅう','보급; 보충 공급','不足した物資・燃料・食料などを追加して供給すること。','長時間の作業に備え、水分と食料を定期的に補給できる体制を整えた。','장시간 작업에 대비해 수분과 식량을 정기적으로 보급할 수 있는 체제를 마련했다.'),
('n1-0623','2026-11-06','与党','よとう','여당; 집권당','政権を担当している政党。','法案を巡って与党内でも意見が分かれ、調整が続いている。','법안을 둘러싸고 여당 내부에서도 의견이 갈려 조정이 계속되고 있다.'),
('n1-0625','2026-11-06','法学','ほうがく','법학','法律・法制度・法の解釈や運用を研究する学問。','大学では法学を専攻し、行政法と労働法を中心に研究した。','대학에서는 법학을 전공하고 행정법과 노동법을 중심으로 연구했다.'),
('n1-0627','2026-11-06','技能','ぎのう','기능; 숙련된 기술','訓練や経験によって身につけた実務的・技術的な能力。','資格試験では知識だけでなく、実際の作業に必要な技能も評価される。','자격시험에서는 지식뿐 아니라 실제 작업에 필요한 기능도 평가된다.'),
('n1-0628','2026-11-06','補足','ほそく','보충 설명; 보완','不足している説明・情報などを付け加って補うこと。','誤解を避けるため、担当者が会議の最後に前提条件を補足した。','오해를 피하기 위해 담당자가 회의 마지막에 전제 조건을 보충 설명했다.'),
('n1-0629','2026-11-06','本音','ほんね','속마음; 진심; 본심','建前ではなく、心の中で実際に思っていること。','匿名のアンケートにしたことで、利用者の本音に近い意見が集まった。','익명 설문으로 바꾸자 이용자의 속마음에 가까운 의견이 모였다.'),
('n1-0630','2026-11-06','不況','ふきょう','불황','経済活動が低迷し、生産・消費・雇用などが落ち込んでいる状態。','長引く不況の影響で、設備投資を延期する企業が増えている。','장기 불황의 영향으로 설비 투자를 연기하는 기업이 늘고 있다.'),
('n1-0632','2026-11-07','理屈','りくつ','이치; 논리; 이론상의 설명','物事の筋道や論理。また、もっともらしく組み立てた説明。','理屈では理解できても、実際に操作してみないと身につかない技術も多い。','이론상으로는 이해해도 실제로 조작해 보지 않으면 익히기 어려운 기술도 많다.'),
('n1-0634','2026-11-07','講習','こうしゅう','강습; 교육 과정','一定の知識・技能を短期間に教え学ぶための授業や研修。','新しい安全基準に対応するため、全社員を対象に講習を実施した。','새 안전 기준에 대응하기 위해 전 직원을 대상으로 강습을 실시했다.'),
('n1-0639','2026-11-07','戸籍','こせき','호적; 가족관계 등록부','出生・婚姻・親子関係など、個人の身分関係を公的に記録する制度・帳簿。','相続手続きでは、関係者の戸籍を確認する必要がある場合がある。','상속 절차에서는 관계자의 호적을 확인해야 하는 경우가 있다.'),
('n1-0640','2026-11-07','追及','ついきゅう','추궁; 책임을 따져 물음','責任・原因・疑惑などを厳しく問い、明らかにしようとすること。','委員会は事故の原因だけでなく、管理責任についても厳しく追及した。','위원회는 사고 원인뿐 아니라 관리 책임에 대해서도 엄격히 추궁했다.'),
('n1-0642','2026-11-07','視察','しさつ','시찰; 현장 점검 방문','現場を訪れ、実際の状況・運営・設備などを見て調べること。','自治体の担当者が工場を視察し、安全対策の実施状況を確認した。','지자체 담당자가 공장을 시찰해 안전 대책의 실시 상황을 확인했다.'),
('n1-0645','2026-11-07','樹立','じゅりつ','수립; 세움','国家・政権・制度・記録などを新たに打ち立てること。','両国は長年の交渉を経て、正式な外交関係を樹立した。','양국은 오랜 협상을 거쳐 정식 외교 관계를 수립했다.'),
('n1-0647','2026-11-07','実情','じつじょう','실정; 실제 사정','表面からは分かりにくい、実際の事情・状態。','制度を改める前に、現場の実情を詳しく調査する必要がある。','제도를 고치기 전에 현장의 실정을 자세히 조사할 필요가 있다.'),
('n1-0648','2026-11-07','家畜','かちく','가축','人が食料・労働・原料などに利用するために飼育する動物。','感染症の拡大を防ぐため、家畜の移動が一時的に制限された。','감염병 확산을 막기 위해 가축 이동이 일시적으로 제한되었다.'),
('n1-0649','2026-11-07','財源','ざいげん','재원; 자금의 출처','事業・政策などに必要な費用をまかなうための資金の出所。','新たな福祉制度を導入するには、安定した財源を確保しなければならない。','새 복지 제도를 도입하려면 안정적인 재원을 확보해야 한다.'),
('n1-0651','2026-11-07','議題','ぎだい','의제; 회의 안건','会議・討論で取り上げ、話し合う対象となる事柄。','次回の会議では、予算配分と人員配置を主要な議題として扱う。','다음 회의에서는 예산 배분과 인원 배치를 주요 의제로 다룬다.'),
('n1-0654','2026-11-07','必然','ひつぜん','필연; 반드시 그렇게 됨','原因・条件から見て、そうなる以外にあり得ないこと。','需要が急増した一方で供給が減れば、価格上昇はある意味で必然だ。','수요가 급증한 반면 공급이 줄면 가격 상승은 어떤 의미에서는 필연이다.'),
('n1-0657','2026-11-07','分担','ぶんたん','분담; 나누어 맡음','仕事・責任・費用などを複数の人や組織で分けて受け持つこと。','調査と資料作成を分担したことで、予定より早く報告書を完成できた。','조사와 자료 작성을 분담해 예정 보다 빨리 보고서를 완성할 수 있었다.'),
('n1-0658','2026-11-07','未知','みち','미지; 아직 알려지지 않음','まだ知られていないこと、または経験したことがないこと。','未知の感染症に備えるには、平時から柔軟な医療体制を整えておく必要がある。','미지의 감염병에 대비하려면 평소부터 유연한 의료 체계를 갖춰둘 필요가 있다.'),
('n1-0659','2026-11-07','好評','こうひょう','호평; 좋은 평가','多くの人から良い評価を受けること、またその評価。','新しい検索機能は操作が分かりやすいと利用者から好評を得ている。','새 검색 기능은 조작이 알기 쉽다는 점에서 이용자들에게 호평을 받고 있다.'),
('n1-0660','2026-11-07','蓄積','ちくせき','축적; 쌓임','知識・経験・資金・データなどが少しずつたまり、増えていくこと。また、ためること。','長年蓄積された利用データを分析し、需要予測の精度を高めた。','오랫동안 축적된 이용 데이터를 분석해 수요 예측의 정확도를 높였다.'),
('n1-0666','2026-11-07','改訂','かいてい','개정; 내용 수정','書物・規程・資料などの内容を見直して修正すること。','法改正に合わせて、社内規程と手順書を全面的に改訂した。','법 개정에 맞춰 사내 규정과 절차서를 전면 개정했다.'),
('n1-0669','2026-11-07','略奪','りゃくだつ','약탈; 강제로 빼앗음','暴力・権力などを用いて他人の財物を奪い取ること。','戦乱の混乱に乗じた略奪を防ぐため、警備が強化された。','전란의 혼란을 틈탄 약탈을 막기 위해 경비가 강화되었다.'),
('n1-0670','2026-11-07','選考','せんこう','전형; 심사하여 선발함','応募者・作品などを基準に照らして審査し、適切なものを選ぶこと。','書類選考を通過した応募者だけが、次の面接に進むことができる。','서류 전형을 통과한 지원자만 다음 면접으로 진행할 수 있다.'),
('n1-0671','2026-11-07','国有','こくゆう','국유; 국가 소유','土地・企業・財産などを国家が所有していること。','国有地の一部を公共施設の建設用地として活用する案が示された。','국유지 일부를 공공시설 건설 부지로 활용하는 방안이 제시되었다.'),
('n1-0673','2026-11-07','出品','しゅっぴん','출품; 상품을 내놓음','作品・商品などを展示会・競売・販売サイトなどに出すこと。','若手作家が国際展に初めて作品を出品し、高い評価を得た。','젊은 작가가 국제전에 처음 작품을 출품해 높은 평가를 받았다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0674','2026-11-08','配分','はいぶん','배분; 몫을 나눔','資金・時間・人員などを一定の基準に従って分け、それぞれに割り当てること。','限られた予算をどの事業にどう配分するかで議論が続いている。','한정된 예산을 어느 사업에 어떻게 배분할지를 두고 논의가 계속되고 있다.'),
('n1-0678','2026-11-08','合間','あいま','틈; 짬; 사이 시간','仕事・作業などが一区切りつく間の短い時間。','会議の合間を利用して、急ぎのメールだけ先に返信した。','회의 사이의 짬을 이용해 급한 메일만 먼저 답장했다.'),
('n1-0691','2026-11-08','加入','かにゅう','가입; 조직·보험 등에 들어감','団体・制度・保険・サービスなどに新たに加わること。','入社後は会社の健康保険に加入するための手続きが必要になる。','입사 후에는 회사 건강보험에 가입하기 위한 절차가 필요하다.'),
('n1-0692','2026-11-08','関税','かんぜい','관세','外国から輸入する商品などに対して国が課す税金。','関税が引き下げられれば、輸入品の価格にも影響が出る可能性がある。','관세가 인하되면 수입품 가격에도 영향이 생길 가능성이 있다.'),
('n1-0693','2026-11-08','分配','ぶんぱい','분배; 나누어 배정함','利益・物資・資源などを複数の相手に分けて配ること。','利益をどのように分配するかは、共同事業を始める前に決めておくべきだ。','이익을 어떻게 분배할지는 공동사업을 시작하기 전에 정해두어야 한다.'),
('n1-0694','2026-11-08','結晶','けっしょう','결정; 결정체','原子・分子・イオンなどが規則正しく並んで一定の形を作った固体。また比喩的に、努力の成果。','この受賞作は、研究者たちの長年にわたる努力の結晶だ。','이 수상작은 연구자들의 오랜 노력의 결정체다.'),
('n1-0696','2026-11-08','目録','もくろく','목록; 목록집','品名・作品名・資料名などを一定の順序でまとめた一覧。','博物館は所蔵資料の目録をデジタル化し、一般公開を始めた。','박물관은 소장 자료 목록을 디지털화해 일반 공개를 시작했다.'),
('n1-0728','2026-11-08','同等','どうとう','동등; 같은 수준','等級・程度・価値・能力などが同じであること。','この資格は大学卒業と同等の知識を証明するものではない。','이 자격은 대학 졸업과 동등한 지식을 증명하는 것은 아니다.'),
('n1-0731','2026-11-08','有望','ゆうぼう','유망함; 장래성이 있음','将来の成功・発展が期待でき、見込みがあるさま。','再生可能エネルギーは今後さらに成長が期待される有望な分野だ。','재생에너지는 앞으로 더욱 성장이 기대되는 유망한 분야다.'),
('n1-0752','2026-11-08','素朴','そぼく','소박함; 꾸밈없음','飾り気がなく、自然で単純なさま。また、考え方などが純真で込み入っていないさま。','派手さはないが、素材の味を生かした素朴な料理が人気だ。','화려하진 않지만 재료의 맛을 살린 소박한 요리가 인기다.'),
('n1-0754','2026-11-08','元来','がんらい','원래; 본래','もともと。初めからそうであることを表す語。','この地域は元来雨が少なく、水の確保が重要な課題だった。','이 지역은 원래 비가 적어 물 확보가 중요한 과제였다.'),
('n1-0767','2026-11-08','半端','はんぱ','어중간함; 불완전함; 중途반단','数量・状態・程度などが中途半端で、まとまりや十分さに欠けるさま。','半端な知識のまま作業を進めると、かえって大きなミスにつながる。','어중간한 지식으로 작업을 진행하면 오히려 큰 실수로 이어진다.'),
('n1-0777','2026-11-08','自在','じざい','자유자재; 마음대로 다룸','思いどおりに自由に扱ったり動かしたりできるさま。','熟練した職人は、この道具を自在に操って複雑な形を作り出す。','숙련된 장인은 이 도구를 자유자재로 다뤄 복잡한 형태를 만들어 낸다.'),
('n1-0782','2026-11-08','気軽','きがる','가벼운 마음; 부담 없음; 편하게','深く心配したり遠慮したりせず、楽な気持ちで行動できるさま。','分からないことがあれば、気軽に担当者へ相談してください。','모르는 것이 있으면 부담 없이 담당자에게 상담해 주세요.'),
('n1-0785','2026-11-08','公然','こうぜん','공공연히; 숨김없이','隠すことなく、周囲に知られる形ではっきり行うさま。','規則に反する行為が公然と行われている状況は見過ごせない。','규칙에 어긋나는 행위가 공공연히 이루어지는 상황은 묵과할 수 없다.'),
('n1-0788','2026-11-08','万能','ばんのう','만능; 무엇에나 쓸 수 있음','あらゆることに優れ、さまざまな目的・状況に対応できるさま。','便利な技術であっても万能ではなく、使い方によっては欠点もある。','편리한 기술이라도 만능은 아니며 사용법에 따라 단점도 있다.'),
('n1-0789','2026-11-08','優勢','ゆうせい','우세; 더 유리함','相手より勢力・能力・状況などが勝っていて有利であること。','序盤は相手が優勢だったが、後半に流れが大きく変わった。','초반에는 상대가 우세했지만 후반에 흐름이 크게 바뀌었다.'),
('n1-0815','2026-11-08','無邪気','むじゃき','천진난만함; 순진무구함','悪意や疑いがなく、子どものように素直で純真なさま。','子どもたちは結果を気にせず、無邪気に水遊びを楽しんでいた。','아이들은 결과를 신경 쓰지 않고 천진난만하게 물놀이를 즐기고 있었다.'),
('n1-0824','2026-11-08','健在','けんざい','건재; 여전히 활약함','健康で無事に暮らしていること。また、能力・勢力などが衰えず、今も十分に活躍していること。','引退して十年たっても、その作家の人気は今なお健在だ。','은퇴한 지 10년이 지나도 그 작가의 인기는 여전히 건재하다.'),
('n1-0844','2026-11-08','簡素','かんそ','간소함; 소박하고 단순함','飾りや無駄が少なく、単純で質素なさま。','申請手続きを簡素にして、利用者の負担を減らす方針だ。','신청 절차를 간소하게 해 이용자 부담을 줄일 방침이다.'),
('n1-0850','2026-11-09','単一','たんいつ','단일; 하나뿐임','複数ではなく、一つだけで成り立っているさま。','単一の原因だけで複雑な社会問題を説明することは難しい。','단일 원인만으로 복잡한 사회 문제를 설명하기는 어렵다.'),
('n1-0857','2026-11-09','手軽','てがる','간편함; 손쉽게 할 수 있음','手間・時間・費用があまりかからず、簡単にできるさま。','スマートフォンで手軽に予約できるため、利用者が急増した。','스마트폰으로 간편하게 예약할 수 있어 이용자가 급증했다.'),
('n1-0862','2026-11-09','不服','ふふく','불복; 불만','決定・命令・処分などに納得できず、不満に思うこと。','判定に不服がある場合は、所定の手続きで再審査を申し立てられる。','판정에 불복하는 경우 정해진 절차로 재심사를 신청할 수 있다.'),
('n1-0863','2026-11-09','近々','きんきん','조만간; 머지않아','近いうちに。そう遠くない時期に。','詳細な日程は近々正式に発表される予定だ。','상세 일정은 조만간 정식으로 발표될 예정이다.'),
('n1-0891','2026-11-09','連日','れんじつ','연일; 여러 날 계속','何日も続けて毎日。','猛暑が連日続き、熱中症への注意が呼びかけられている。','폭염이 연일 이어져 열사병 주의가 당부되고 있다.'),
('n1-0895','2026-11-09','小柄','こがら','작은 체구; 몸집이 작음','体格が比較的小さいさま。','彼女は小柄だが、長距離を走る体力には非常に優れている。','그녀는 체구가 작지만 장거리 달리기 체력은 매우 뛰어나다.'),
('n1-0898','2026-11-09','大方','おおかた','대체로; 대부분; 대강','全体の大部分。副詞的には『だいたい・おそらく』の意でも用いる。','作業は大方終わったので、残るのは最終確認だけだ。','작업은 대체로 끝나서 남은 것은 최종 확인뿐이다.'),
('n1-0912','2026-11-09','多忙','たぼう','다망; 매우 바쁨','仕事・用事が非常に多く、忙しいさま。','多忙な時期ほど、優先順位を決めて仕事を整理する必要がある。','매우 바쁜 시기일수록 우선순위를 정해 일을 정리할 필요가 있다.'),
('n1-0931','2026-11-09','断然','だんぜん','단연; 압도적으로','他と比べて明らかに程度が上であるさま。また、きっぱりとしたさま。','複数の案を比較した結果、費用対効果ではこの案が断然優れていた。','여러 안을 비교한 결과 비용 대비 효과에서는 이 안이 단연 뛰어났다.'),
('n1-0946','2026-11-09','単調','たんちょう','단조로움; 변화가 없음','変化が少なく、同じような状態が続いて面白みに欠けるさま。','単調な作業でも、手順を工夫すれば集中力を保ちやすくなる。','단조로운 작업도 절차를 개선하면 집중력을 유지하기 쉬워진다.'),
('n1-0970','2026-11-09','伴う','ともなう','수반하다; 동반하다','ある物事に別の物事が付随して起こる。また、人などを連れて行く。','制度の変更には一定の混乱が伴う可能性がある。','제도 변경에는 일정한 혼란이 수반될 가능성이 있다.'),
('n1-0972','2026-11-09','極めて','きわめて','극히; 매우','程度が非常に高いことを表す語。','この判断は今後の事業方針を左右するため、極めて重要である。','이 판단은 향후 사업 방침을 좌우하므로 매우 중요하다.'),
('n1-0976','2026-11-09','記す','しるす','기록하다; 적다','文字・文章として書き残す。また、印などで示す。','調査結果は報告書に正確に記しておく必要がある。','조사 결과는 보고서에 정확히 기록해 둘 필요가 있다.'),
('n1-0980','2026-11-09','止める','とどめる','머물게 하다; 그치게 하다; 범위에 한정하다','進行・拡大などをある範囲で止める。また、人・物をその場所に残す。','被害を最小限に止めるため、早期の対応が求められる。','피해를 최소한으로 그치게 하기 위해 조기 대응이 요구된다.'),
('n1-1001','2026-11-09','称する','しょうする','칭하다; 일컫다; 자칭하다','ある名称で呼ぶ。また、自分をそのように名乗る・装う。','彼は専門家を称しているが、その分野での実務経験は確認できない。','그는 전문가를 자칭하지만 그 분야의 실무 경험은 확인되지 않는다.'),
('n1-1018','2026-11-09','難い','かたい','~하기 어렵다; 쉽지 않다','『〜し難い』の形で、その行為をするのが難しいことを表す。','長年の経験から得た知識は、数字だけでは説明し難い。','오랜 경험에서 얻은 지식은 숫자만으로 설명하기 어렵다.'),
('n1-1022','2026-11-09','正に','まさに','바로; 바로 그; 틀림없이','まちがいなくそのとおりであること、またはちょうどその時であることを強く示す語。','この発見は、長年探していた問題解決の手掛かりに正になり得る。','이 발견은 오랫동안 찾던 문제 해결의 실마리가 바로 될 수 있다.'),
('n1-1026','2026-11-09','益々','ますます','더욱더; 갈수록','程度・傾向が以前よりさらに強くなるさま。通常はひらがなで書くことが多い。','人口減少が進めば、地域交通の維持は益々難しくなる。','인구 감소가 진행되면 지역 교통 유지가 갈수록 어려워진다.'),
('n1-1031','2026-11-09','無礼','ぶれい','무례; 예의 없음','礼儀を欠いていること。相手に対して失礼なこと。','初対面の相手にそのような質問をするのは無礼に当たる。','처음 만난 상대에게 그런 질문을 하는 것은 무례에 해당한다.'),
('n1-1032','2026-11-09','一気','いっき','단숨에; 한꺼번에','途中で休まず、ひと続きに物事を行うこと。また、急激に進むさま。','制度を一気に変えるのではなく、段階的に移行する方針だ。','제도를 단숨에 바꾸는 것이 아니라 단계적으로 전환할 방침이다.');
INSERT INTO _n1_b3_words_0101(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1033','2026-11-10','尽くす','つくす','다하다; 힘을 쏟다; 모두 써버리다','力・能力などを残さず出す。また、ある人・目的のために精一杯努力する。','担当者は利用者への説明責任を果たすため、最後まで力を尽くした。','담당자는 이용자에 대한 설명 책임을 다하기 위해 끝까지 힘을 쏟았다.'),
('n1-1043','2026-11-10','要する','ようする','필요로 하다; 요하다','時間・費用・努力などを必要とする。','この手続きは完了までに通常二週間程度を要する。','이 절차는 완료까지 보통 2주 정도가 필요하다.'),
('n1-1062','2026-11-10','臆病','おくびょう','겁이 많음; 소심함','怖がりで、危険・困難に対してすぐ不安になるさま。','失敗を恐れて臆病になりすぎると、新しい挑戦ができなくなる。','실패를 두려워해 지나치게 소심해지면 새로운 도전을 할 수 없게 된다.'),
('n1-1076','2026-11-10','若干','じゃっかん','약간; 다소; 약간 명','数量・程度がそれほど多くないこと。また、人数が少数であること。','前年度と比べて売上は若干減少したが、利益率は改善した。','전년도와 비교해 매출은 다소 감소했지만 이익률은 개선됐다.'),
('n1-1080','2026-11-10','止まる','とどまる','머물다; 그치다; 범위를 넘지 않다','その場所・状態に残る。また、一定の範囲・程度を越えない。','被害は一地域にとどまらず、周辺の自治体にも広がった。','피해는 한 지역에 그치지 않고 주변 지자체에도 확산됐다.'),
('n1-1087','2026-11-10','弾く','はじく','튕기다; 튀겨 내다; 물리치다','指などで物を勢いよくはね飛ばす。また、水などを表面で受け付けずはね返す。','この素材は水を弾くため、雨天用の衣類にも使われている。','이 소재는 물을 튕겨 내기 때문에 우천용 의류에도 사용된다.'),
('n1-1094','2026-11-10','度々','たびたび','자주; 여러 번','同じことが何度も繰り返されるさま。','同じ障害が度々発生しているため、根本原因の調査が必要だ。','같은 장애가 자주 발생하고 있어 근본 원인 조사가 필요하다.'),
('n1-1095','2026-11-10','次いで','ついで','이어서; 그다음으로','ある物事のすぐ後に続いて。順位・順序がその次であることを表す。','売上は国内市場が最も多く、次いで北米市場となっている。','매출은 국내 시장이 가장 많고 그다음이 북미 시장이다.'),
('n1-1120','2026-11-10','襲う','おそう','습격하다; 덮치다; 엄습하다','人・場所などを突然攻撃する。また、災害・病気・眠気・不安などが急に迫る。','夜中に強い眠気が襲い、作業を中断して休むことにした。','한밤중에 강한 졸음이 엄습해 작업을 중단하고 쉬기로 했다.'),
('n1-1134','2026-11-10','浮かぶ','うかぶ','뜨다; 떠오르다','水面・空中などに浮いている。また、考え・記憶・表情などが心や顔に現れる。','問題点を整理しているうちに、新しい解決策が頭に浮かんだ。','문제점을 정리하다 보니 새로운 해결책이 머릿속에 떠올랐다.'),
('n1-1140','2026-11-10','取り分け','とりわけ','특히; 유달리','多くの中でも特に。格別に。','今年の夏は例年より暑く、八月は取り分け厳しい暑さだった。','올여름은 예년보다 더웠고 8월은 특히 더위가 심했다.'),
('n1-1145','2026-11-10','密か','ひそか','은밀하다; 남몰래','人に知られないように、こっそり行うさま。','彼は数年前から密かに独立の準備を進めていた。','그는 몇 년 전부터 남몰래 독립 준비를 진행하고 있었다.'),
('n1-1146','2026-11-10','強める','つよめる','강화하다; 세게 하다','力・程度・影響・態度などを以前より強くする。','情報漏えいを防ぐため、アクセス制限をさらに強めた。','정보 유출을 막기 위해 접근 제한을 더욱 강화했다.'),
('n1-1154','2026-11-10','添える','そえる','곁들이다; 덧붙이다; 붙이다','主となるもののそばに別のものを付け加える。言葉・品物・料理などを加える場合にもいう。','申請書には本人確認書類の写しを添えて提出してください。','신청서에는 본인 확인 서류 사본을 첨부해 제출해 주세요.'),
('n1-1164','2026-11-10','告げる','つげる','알리다; 고하다','事実・決定・時の到来などを相手に知らせる。','担当者は会議の終了を告げ、参加者に資料を配った。','담당자는 회의 종료를 알리고 참가자들에게 자료를 배포했다.'),
('n1-1169','2026-11-10','手遅れ','ておくれ','때를 놓침; 이미 늦음','対応すべき時期を逃し、今から手を打っても間に合わないこと。','異常を放置すると手遅れになるおそれがあるため、早めの点検が必要だ。','이상을 방치하면 때를 놓칠 우려가 있어 조기 점검이 필요하다.'),
('n1-1176','2026-11-10','最早','もはや','이미; 이제는 더 이상','今となってはすでに。多く、以前の状態には戻れないという意味を伴う。','この技術はもはや一部の専門家だけが使うものではない。','이 기술은 이제 더 이상 일부 전문가만 사용하는 것이 아니다.'),
('n1-1179','2026-11-10','交わす','かわす','주고받다; 나누다','言葉・挨拶・約束・杯などを互いにやり取りする。','会議の前に担当者同士で簡単な挨拶を交わした。','회의 전에 담당자끼리 간단한 인사를 주고받았다.'),
('n1-1184','2026-11-10','引き起こす','ひきおこす','일으키다; 야기하다','事件・問題・変化・感情などを生じさせる。','設定ミスが大規模なシステム障害を引き起こした。','설정 실수가 대규모 시스템 장애를 일으켰다.'),
('n1-1203','2026-11-10','専ら','もっぱら','주로; 오로지','ほとんどそれだけに集中しているさま。','最近は通勤時間をもっぱら資格試験の勉強に使っている。','최근에는 통근 시간을 주로 자격시험 공부에 쓰고 있다.'),
('n1-1204','2026-11-11','溢れる','あふれる','넘치다; 가득하다','容器・場所などがいっぱいになって外へ出る。また、感情・活気などが非常に豊かに現れる。','会場は新しい技術への期待に溢れた参加者でいっぱいだった。','행사장은 새로운 기술에 대한 기대가 넘치는 참가자들로 가득했다.'),
('n1-1212','2026-11-11','貫く','つらぬく','관철하다; 끝까지 지키다; 꿰뚫다','物を端から端まで突き通す。また、信念・方針・態度などを最後まで変えずに守る。','周囲の反対があっても、彼は利用者優先の方針を貫いた。','주변의 반대가 있어도 그는 사용자 우선 방침을 끝까지 관철했다.'),
('n1-1226','2026-11-11','込める','こめる','담다; 넣다; 힘을 주다','気持ち・意味・力などを中に含ませる。また、弾・物などを内部に入れる。','感謝の気持ちを込めて、支えてくれた人たちに手紙を書いた。','감사의 마음을 담아 도와준 사람들에게 편지를 썼다.'),
('n1-1228','2026-11-11','完璧','かんぺき','완벽','欠点・不足がまったくなく、完全であること。','最初から完璧を求めるより、改善を重ねる方が現実的だ。','처음부터 완벽을 추구하기보다 개선을 거듭하는 편이 현실적이다.'),
('n1-1229','2026-11-11','沿う','そう','따르다; ~을 따라가다','線・道・川などに従って進む。また、方針・希望・目的などに合うようにする。','利用者の要望に沿う形で画面構成を見直した。','사용자의 요구에 맞는 형태로 화면 구성을 재검토했다.'),
('n1-1231','2026-11-11','優美','ゆうび','우아함; 아름답고 품위 있음','上品で美しく、落ち着いた趣があるさま。','その建物は曲線を生かした優美なデザインで知られている。','그 건물은 곡선을 살린 우아한 디자인으로 알려져 있다.'),
('n1-1241','2026-11-11','達者','たっしゃ','능숙함; 건강함','ある技能に非常に優れていること。また、体が丈夫で元気なこと。','彼は外国語が達者で、会議でも通訳なしで意見を述べる。','그는 외국어에 능숙해서 회의에서도 통역 없이 의견을 말한다.'),
('n1-1261','2026-11-11','うんざり','うんざり','진절머리 남; 싫증이 남','同じことが続いたり不快なことが重なったりして、すっかり嫌になるさま。','同じ説明を何度も聞かされて、さすがにうんざりした。','같은 설명을 몇 번이나 들어서 역시 진절머리가 났다.'),
('n1-1262','2026-11-11','勝る','まさる','능가하다; 더 낫다','能力・品質・程度などが他より優れている。','使いやすさの点では旧製品より新製品の方が勝っている。','사용 편의성 면에서는 구제품보다 신제품이 더 낫다.'),
('n1-1267','2026-11-11','痛む','いたむ','아프다; 상하다','体の一部に痛みを感じる。また、食べ物・物などが傷んで悪くなる。','長時間同じ姿勢で作業したため、腰が痛むようになった。','오랫동안 같은 자세로 작업해서 허리가 아프기 시작했다.'),
('n1-1273','2026-11-11','質素','しっそ','검소함; 소박함','ぜいたくを避け、飾り気が少なく簡素であるさま。','彼は高い収入を得ても質素な生活を続けている。','그는 높은 수입을 올려도 검소한 생활을 계속하고 있다.'),
('n1-1282','2026-11-11','追い込む','おいこむ','몰아넣다; 궁지로 몰다','人・動物などをある場所へ追って入れる。また、相手を逃げ道のない困難な状況に陥らせる。','過度な納期短縮は現場を厳しい状況に追い込むおそれがある。','지나친 납기 단축은 현장을 어려운 상황으로 몰아넣을 우려가 있다.'),
('n1-1283','2026-11-11','赴く','おもむく','가다; 향하다; 부임하다','ある場所・任務・方向へ向かって行く。','担当者は現地調査のため被災地域へ赴いた。','담당자는 현지 조사를 위해 피해 지역으로 향했다.'),
('n1-1300','2026-11-11','吐く','つく','(거짓말·한숨 등을) 내뱉다; 하다','『嘘をつく』『ため息をつく』など、一定の表現で口から言葉・息などを出す意味を表す。','その場を逃れるために嘘を吐くのは、問題をさらに大きくする。','그 자리를 모면하려고 거짓말을 하는 것은 문제를 더 키운다.'),
('n1-1318','2026-11-11','ほっと','ほっと','안도하여 마음이 놓이는 모양','緊張・心配などが解けて安心するさま。','検査結果に問題がないと聞いて、家族全員がほっとした。','검사 결과에 문제가 없다는 말을 듣고 가족 모두가 안도했다.'),
('n1-1321','2026-11-11','漂う','ただよう','떠다니다; 감돌다; 풍기다','空中・水面などを定まった方向なく浮いて移動する。また、香り・雰囲気・気配などが周囲に感じられる。','会場には開演前から緊張した空気が漂っていた。','행사장에는 개막 전부터 긴장된 분위기가 감돌고 있었다.'),
('n1-1323','2026-11-11','態々','わざわざ','일부러; 모처럼 수고해서','そのためだけに特別に手間や時間をかけて行うさま。通常は『わざわざ』と書く。','忙しい中、わざわざ説明に来ていただきありがとうございます。','바쁜 와중에 일부러 설명하러 와 주셔서 감사합니다.'),
('n1-1328','2026-11-11','気まぐれ','きまぐれ','변덕스러움; 변덕','その時々の気分によって考えや行動が変わり、一定しないさま。','彼の気まぐれな判断に振り回されないよう、手順を明文化した。','그의 변덕스러운 판단에 휘둘리지 않도록 절차를 명문화했다.'),
('n1-1333','2026-11-11','柔軟','じゅうなん','유연함; 융통성 있음','物がしなやかで曲がりやすいさま。また、考え方・対応が状況に応じて変えられるさま。','想定外の変更にも柔軟に対応できる設計が望ましい。','예상 밖의 변경에도 유연하게 대응할 수 있는 설계가 바람직하다.'),
('n1-1334','2026-11-11','尽きる','つきる','다하다; 바닥나다; 끝나다','数量・力・話題・命などがすべてなくなり、それ以上続かなくなる。','議論は尽きないが、今日はここで結論をまとめることにした。','논의는 끝이 없지만 오늘은 여기서 결론을 정리하기로 했다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-10-29..2026-11-11' FROM _n1_b3_words_0101 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b3_map_0101(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b3_words_0101 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
