INSERT INTO japanese_jlpt_daily_words(session_id,word_id,item_kind) SELECT ds.id,m.word_id,'new' FROM _n1_b3_words_0101 s JOIN _n1_b3_map_0101 m ON m.source_key=s.source_key JOIN japanese_jlpt_daily_sessions ds ON ds.study_date=s.study_date JOIN japanese_jlpt_study_plans p ON p.id=ds.plan_id WHERE p.plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1771","prompt":"「即ち」の読み方として最も適切なものを選びなさい。","options":["おくびょう","じゅうなん","てがる","すなわち"],"answer":"すなわち","explanationKo":"「即ち」는 「すなわち」라고 읽는다. 뜻은 즉; 다시 말해이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1615","prompt":"「閉口」の読み方として最も適切なものを選びなさい。","options":["かにゅう","じく","へいこう","かいぼう"],"answer":"へいこう","explanationKo":"「閉口」는 「へいこう」라고 읽는다. 뜻은 질림; 곤란해함; 두 손 듦이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1625","prompt":"「船舶」の読み方として最も適切なものを選びなさい。","options":["さっかく","せんぱく","まちあわせ","ざいげん"],"answer":"せんぱく","explanationKo":"「船舶」는 「せんぱく」라고 읽는다. 뜻은 선박이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1628","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n税制度では（　）する家族の人数が控除額に影響する場合がある。","options":["扶養","茶の湯","経路","産物"],"answer":"扶養","explanationKo":"문맥상 「扶養」가 가장 자연스럽다. 부양라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
