INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','grammar',1,'〜をよそに','{"pattern":"〜をよそに","meaningKo":"〜을 아랑곳하지 않고","explanation":"〜をよそに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"周囲の心配をよそに、本人は新しい計画を進めた。","ko":"문맥에서 〜을 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"住民の反対をよそに、工事は予定どおり始まった。","ko":"이 문장도 〜을 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','grammar',2,'〜を限りに','{"pattern":"〜を限りに","meaningKo":"〜을 마지막으로","explanation":"〜を限りに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"本日の公演を限りに、この劇場は閉館する。","ko":"문맥에서 〜을 마지막으로의 의미로 쓰였다."},{"ja":"今月を限りに、長年続けた仕事を退くことにした。","ko":"이 문장도 〜을 마지막으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n周囲の心配（　）、本人は新しい計画を進めた。","options":["〜をよそに","〜に至っては","〜に則って","〜べくもない"],"answer":"〜をよそに","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をよそに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本日の公演（　）、この劇場は閉館する。","options":["〜に至っても","〜に照らして","〜んがため","〜を限りに"],"answer":"〜を限りに","explanationKo":"문맥상 〜을 마지막으로를 나타내는 「〜を限りに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n突然の知らせに彼が動揺したことは理解（　）。","options":["〜に先駆けて","〜んばかりに","〜にかたくない","〜にあって"],"answer":"〜にかたくない","explanationKo":"문맥상 〜하기 어렵지 않다를 나타내는 「〜にかたくない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-29','reading',1,'慣行を見直す視点','{"passage":"長く続いた慣行を見直すことには、現在の目的に合わない負担を減らせることという意義がある。ただし、由来を確かめずに廃止すると必要な役割まで失うこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、成立した理由と現在の効果を分けて検討することが重要である。","questions":[{"prompt":"「慣行を見直す視点」について筆者が重要だと述べることは何か。","options":["成立した理由と現在の効果を分けて検討すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"成立した理由と現在の効果を分けて検討すること","explanationKo":"본문의 결론은 成立した理由と現在の効果を分けて検討すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["由来を確かめずに廃止すると必要な役割まで失うこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"由来を確かめずに廃止すると必要な役割まで失うこと","explanationKo":"본문에서는 由来を確かめずに廃止すると必要な役割まで失うこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["現在の目的に合わない負担を減らせること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"現在の目的に合わない負担を減らせること","explanationKo":"長く続いた慣行を見直すこと에는 現在の目的に合わない負担を減らせること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1916","prompt":"「切っ掛け」の読み方として最も適切なものを選びなさい。","options":["きっかけ","こころざし","ぶんかざい","むすびつき"],"answer":"きっかけ","explanationKo":"「切っ掛け」는 「きっかけ」라고 읽는다. 뜻은 계기; 기회; 발단이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
