INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1890","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年度は採用（　）を広げ、より多様な人材を受け入れる方針だ。","options":["動向","枠","衆議院","茶の湯"],"answer":"枠","explanationKo":"문맥상 「枠」가 가장 자연스럽다. 틀; 테두리; 범위; 한도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1892","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n顧客の利便性を（　）に、サービス全体の設計を見直した。","options":["軸","連盟","異議","社交"],"answer":"軸","explanationKo":"문맥상 「軸」가 가장 자연스럽다. 축; 중심축; 중심이 되는 기준라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1893","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n急速な（　）によって生活必需品の価格が大きく上昇した。","options":["慣習","本音","扶養","インフレ"],"answer":"インフレ","explanationKo":"문맥상 「インフレ」가 가장 자연스럽다. 인플레이션; 물가의 지속적 상승라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1905","prompt":"「広い敷地を持つ、規模が大きく立派な住宅。」という意味に最も近い語を選びなさい。","options":["兼業","出世","邸宅","結晶"],"answer":"邸宅","explanationKo":"「邸宅」의 핵심 의미는 저택; 규모가 큰 주택이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1922","prompt":"「物事の中心となる部分。また、原子核・細胞核などのように、中心部を構成するもの。」という意味に最も近い語を選びなさい。","options":["適応","核","照合","偽造"],"answer":"核","explanationKo":"「核」의 핵심 의미는 핵; 중심; 핵심이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1964","prompt":"「光がなく暗いこと。また、表に出ない不正・違法な領域。」という意味に最も近い語を選びなさい。","options":["闇","配給","略奪","志"],"answer":"闇","explanationKo":"「闇」의 핵심 의미는 어둠; 암흑; 불법·은밀한 영역이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1966","prompt":"「法律に基づいて犯罪者に科される罰。」という意味に最も近い語を選びなさい。","options":["果て","衆議院","茶の湯","刑"],"answer":"刑","explanationKo":"「刑」의 핵심 의미는 형벌; 형이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1976","prompt":"「借りていた物・土地・権利などを元の持ち主へ返すこと。」という意味に最も近い語を選びなさい。","options":["刊行","蓄積","返還","倒産"],"answer":"返還","explanationKo":"「返還」의 핵심 의미는 반환; 돌려줌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','grammar',1,'〜にかたくない','{"pattern":"〜にかたくない","meaningKo":"〜하기 어렵지 않다","explanation":"〜にかたくない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"被災した人々の不安は想像にかたくない。","ko":"문맥에서 〜하기 어렵지 않다의 의미로 쓰였다."},{"ja":"突然の知らせに彼が動揺したことは理解にかたくない。","ko":"이 문장도 〜하기 어렵지 않다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','grammar',2,'〜にひきかえ','{"pattern":"〜にひきかえ","meaningKo":"〜와 대조적으로","explanation":"〜にひきかえ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"兄が社交的なのにひきかえ、弟は物静かだ。","ko":"문맥에서 〜와 대조적으로의 의미로 쓰였다."},{"ja":"好調だった前期にひきかえ、今期は売上が落ち込んだ。","ko":"이 문장도 〜와 대조적으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n被災した人々の不安は想像（　）。","options":["〜にあって","〜に先駆けて","〜んばかりに","〜にかたくない"],"answer":"〜にかたくない","explanationKo":"문맥상 〜하기 어렵지 않다를 나타내는 「〜にかたくない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n兄が社交的なの（　）、弟は物静かだ。","options":["〜に先立って","〜とばかりに","〜にひきかえ","〜にして"],"answer":"〜にひきかえ","explanationKo":"문맥상 〜와 대조적으로를 나타내는 「〜にひきかえ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n交渉が最終段階（　）、新たな問題が判明した。","options":["〜と相まって","〜に至って","〜にしてはじめて","〜にこしたことはない"],"answer":"〜に至って","explanationKo":"문맥상 〜에 이르러서를 나타내는 「〜に至って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-30','reading',1,'支援と自立の関係','{"passage":"困っている人を支援することには、当面の負担を軽くして再出発を助けられることという意義がある。ただし、支援する側がすべてを決めると本人の判断機会を奪うこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、本人が選べる範囲を広げる形で支えることが重要である。","questions":[{"prompt":"「支援と自立の関係」について筆者が重要だと述べることは何か。","options":["本人が選べる範囲を広げる形で支えること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"本人が選べる範囲を広げる形で支えること","explanationKo":"본문의 결론은 本人が選べる範囲を広げる形で支えること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["支援する側がすべてを決めると本人の判断機会を奪うこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"支援する側がすべてを決めると本人の判断機会を奪うこと","explanationKo":"본문에서는 支援する側がすべてを決めると本人の判断機会を奪うこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["当面の負担を軽くして再出発を助けられること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"当面の負担を軽くして再出発を助けられること","explanationKo":"困っている人を支援すること에는 当面の負担を軽くして再出発を助けられること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2094","prompt":"「合議」の読み方として最も適切なものを選びなさい。","options":["とうそつ","ごうぎ","ぎだい","さいくつ"],"answer":"ごうぎ","explanationKo":"「合議」는 「ごうぎ」라고 읽는다. 뜻은 합의; 협의; 여러 사람이 의논함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
