INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2207","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会社の規定で（　）が認められている。","options":["闇","好況","兼業","物議"],"answer":"兼業","explanationKo":"문맥상 「兼業」가 가장 자연스럽다. 겸업; 부업 겸함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
