INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2313","prompt":"「地下などに埋めて保存すること。また、地下に資源・遺物などが存在すること。」という意味に最も近い語を選びなさい。","options":["義理","炭素","埋蔵","跡継ぎ"],"answer":"埋蔵","explanationKo":"「埋蔵」의 핵심 의미는 매장; 땅속에 묻혀 있음; 매장되어 보존됨이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2315","prompt":"「沿岸国の主権が及ぶ、海岸から一定範囲の海域。」という意味に最も近い語を選びなさい。","options":["分担","領海","自覚","着手"],"answer":"領海","explanationKo":"「領海」의 핵심 의미는 영해이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
