INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2329","prompt":"「評判・評価が悪いこと。人々に好まれていないこと。」という意味に最も近い語を選びなさい。","options":["核","好況","座談会","不評"],"answer":"不評","explanationKo":"「不評」의 핵심 의미는 악평; 평판이 나쁨; 인기 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','grammar',1,'〜に至って','{"pattern":"〜に至って","meaningKo":"〜에 이르러서","explanation":"〜に至って는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事態が深刻になるに至って、ようやく対策が始まった。","ko":"문맥에서 〜에 이르러서의 의미로 쓰였다."},{"ja":"交渉が最終段階に至って、新たな問題が判明した。","ko":"이 문장도 〜에 이르러서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','grammar',2,'〜に至っては','{"pattern":"〜に至っては","meaningKo":"〜에 이르러서는","explanation":"〜に至っては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"責任者に至っては、会議に姿さえ見せなかった。","ko":"문맥에서 〜에 이르러서는의 의미로 쓰였다."},{"ja":"最終案に至っては、当初の目的まで失われている。","ko":"이 문장도 〜에 이르러서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事態が深刻になる（　）、ようやく対策が始まった。","options":["〜にこしたことはない","〜と相まって","〜に至って","〜にしてはじめて"],"answer":"〜に至って","explanationKo":"문맥상 〜에 이르러서를 나타내는 「〜に至って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者（　）、会議に姿さえ見せなかった。","options":["〜ないではおかない","〜に至っては","〜にかこつけて","〜には及ばない"],"answer":"〜に至っては","explanationKo":"문맥상 〜에 이르러서는를 나타내는 「〜に至っては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの段階（　）、原因は特定されていない。","options":["〜に至っても","〜に則って","〜まじき","〜ないではすまない"],"answer":"〜に至っても","explanationKo":"문맥상 〜에 이르러도를 나타내는 「〜に至っても」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-31','reading',1,'専門用語を共有する','{"passage":"専門用語の意味を組織内で共有することには、短い言葉で複雑な状況を正確に伝えられることという意義がある。ただし、理解を確認しなければ同じ言葉を別の意味で使うこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、定義と具体例を一緒に確認することが重要である。","questions":[{"prompt":"「専門用語を共有する」について筆者が重要だと述べることは何か。","options":["定義と具体例を一緒に確認すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"定義と具体例を一緒に確認すること","explanationKo":"본문의 결론은 定義と具体例を一緒に確認すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["理解を確認しなければ同じ言葉を別の意味で使うこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"理解を確認しなければ同じ言葉を別の意味で使うこと","explanationKo":"본문에서는 理解を確認しなければ同じ言葉を別の意味で使うこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["短い言葉で複雑な状況を正確に伝えられること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"短い言葉で複雑な状況を正確に伝えられること","explanationKo":"専門用語の意味を組織内で共有すること에는 短い言葉で複雑な状況を正確に伝えられること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2436","prompt":"「公」の読み方として最も適切なものを選びなさい。","options":["ついきゅう","かんこう","おおやけ","そうりつ"],"answer":"おおやけ","explanationKo":"「公」는 「おおやけ」라고 읽는다. 뜻은 공적임; 공공; 공식적인 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2460","prompt":"「隠居」の読み方として最も適切なものを選びなさい。","options":["こうたい","いんきょ","けいしゃ","こんけつ"],"answer":"いんきょ","explanationKo":"「隠居」는 「いんきょ」라고 읽는다. 뜻은 은퇴; 은거; 은퇴한 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2468","prompt":"「保障」の読み方として最も適切なものを選びなさい。","options":["ほしょう","きゅうさい","ほうしゅつ","ほそく"],"answer":"ほしょう","explanationKo":"「保障」는 「ほしょう」라고 읽는다. 뜻은 보장; 보호이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2470","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n相手の攻撃に備えて（　）を取った。","options":["手元","総会","割り当て","構え"],"answer":"構え","explanationKo":"문맥상 「構え」가 가장 자연스럽다. 자세; 태세; 구조; 외관라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2506","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n家庭での（　）は子どもの生活習慣に大きく影響する。","options":["必然","失格","躾","風俗"],"answer":"躾","explanationKo":"문맥상 「躾」가 가장 자연스럽다. 예절 교육; 훈육; 가정교육라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2521","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）ではなく、本当に素晴らしい作品だと思う。","options":["自覚","お世辞","回覧","橋渡し"],"answer":"お世辞","explanationKo":"문맥상 「お世辞」가 가장 자연스럽다. 빈말; 아첨; 듣기 좋은 말라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2527","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n京都で（　）の作法を体験した。","options":["茶の湯","到達","創立","追及"],"answer":"茶の湯","explanationKo":"문맥상 「茶の湯」가 가장 자연스럽다. 다도; 일본식 차 의식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2528","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n受付の（　）に会場までの道を尋ねた。","options":["補給","畜産","核","係り"],"answer":"係り","explanationKo":"문맥상 「係り」가 가장 자연스럽다. 담당자; 담당; 맡은 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2562","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は若くして成功した（　）として知られている。","options":["領海","議事堂","実業家","インフレ"],"answer":"実業家","explanationKo":"문맥상 「実業家」가 가장 자연스럽다. 실업가; 기업가; 사업가라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2566","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地域社会との（　）が強い会社だ。","options":["総会","結び付き","跡継ぎ","手元"],"answer":"結び付き","explanationKo":"문맥상 「結び付き」가 가장 자연스럽다. 연결; 관계; 결부라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2577","prompt":"「薬・方法などによって現れる効果。」という意味に最も近い語を選びなさい。","options":["効き目","人体","風俗","必然"],"answer":"効き目","explanationKo":"「効き目」의 핵심 의미는 효과; 효험; 약효이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2581","prompt":"「家業・地位・財産などを引き継ぐ人。」という意味に最も近い語を選びなさい。","options":["家畜","回覧","橋渡し","跡継ぎ"],"answer":"跡継ぎ","explanationKo":"「跡継ぎ」의 핵심 의미는 후계자; 대를 이을 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2603","prompt":"「不要なものを取り除くために通過させる装置。また、写真・映像などの効果用具。」という意味に最も近い語を選びなさい。","options":["到達","創立","フィルター","隠居"],"answer":"フィルター","explanationKo":"「フィルター」의 핵심 의미는 필터; 여과 장치이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2702","prompt":"「抗議などの目的で、参加・購入・取引などを集団で拒否すること。」という意味に最も近い語を選びなさい。","options":["傾斜","ボイコット","打ち合わせ","不況"],"answer":"ボイコット","explanationKo":"「ボイコット」의 핵심 의미는 보이콧; 집단 거부이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2714","prompt":"「多数の意見に従って決定する方法。」という意味に最も近い語を選びなさい。","options":["多数決","分配","インフレ","領海"],"answer":"多数決","explanationKo":"「多数決」의 핵심 의미는 다수결이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','grammar',1,'〜に至っても','{"pattern":"〜に至っても","meaningKo":"〜에 이르러도","explanation":"〜に至っても는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"期限直前に至っても、意見はまとまらなかった。","ko":"문맥에서 〜에 이르러도의 의미로 쓰였다."},{"ja":"この段階に至っても、原因は特定されていない。","ko":"이 문장도 〜에 이르러도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','grammar',2,'〜にあって','{"pattern":"〜にあって","meaningKo":"〜라는 상황에서","explanation":"〜にあって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"厳しい状況にあって、現場は冷静な対応を続けた。","ko":"문맥에서 〜라는 상황에서의 의미로 쓰였다."},{"ja":"変革期にあって、柔軟な判断が求められている。","ko":"이 문장도 〜라는 상황에서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n期限直前（　）、意見はまとまらなかった。","options":["〜ないではすまない","〜に至っても","〜に則って","〜まじき"],"answer":"〜に至っても","explanationKo":"문맥상 〜에 이르러도를 나타내는 「〜に至っても」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n厳しい状況（　）、現場は冷静な対応を続けた。","options":["〜にあって","〜に照らして","〜べく","〜ともなく"],"answer":"〜にあって","explanationKo":"문맥상 〜라는 상황에서를 나타내는 「〜にあって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの困難な作業を一日で終えたのは、彼（　）可能だった。","options":["〜に先駆けて","〜べくもない","〜ながらに","〜にして"],"answer":"〜にして","explanationKo":"문맥상 〜이면서; 〜에야를 나타내는 「〜にして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-01','reading',1,'失敗の記録を残す','{"passage":"失敗の経緯を記録することには、同じ条件で問題が再発するのを防げることという意義がある。ただし、個人の責任追及だけに使うと報告されなくなることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、判断材料と改善点を中心に記録することが重要である。","questions":[{"prompt":"「失敗の記録を残す」について筆者が重要だと述べることは何か。","options":["判断材料と改善点を中心に記録すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"判断材料と改善点を中心に記録すること","explanationKo":"본문의 결론은 判断材料と改善点を中心に記録すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["個人の責任追及だけに使うと報告されなくなること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"個人の責任追及だけに使うと報告されなくなること","explanationKo":"본문에서는 個人の責任追及だけに使うと報告されなくなること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["同じ条件で問題が再発するのを防げること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"同じ条件で問題が再発するのを防げること","explanationKo":"失敗の経緯を記録すること에는 同じ条件で問題が再発するのを防げること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2925","prompt":"「にも拘らず」の読み方として最も適切なものを選びなさい。","options":["かんしゅう","ほうがく","みち","にもかかわらず"],"answer":"にもかかわらず","explanationKo":"「にも拘らず」는 「にもかかわらず」라고 읽는다. 뜻은 ~에도 불구하고이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
