INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2968","prompt":"「伝来」の読み方として最も適切なものを選びなさい。","options":["でんたつ","でんらい","ストライキ","しゅっせ"],"answer":"でんらい","explanationKo":"「伝来」는 「でんらい」라고 읽는다. 뜻은 전래; 전해 내려옴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2976","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n監督はチームを見事に（　）した。","options":["統率","偽造","適応","配分"],"answer":"統率","explanationKo":"문맥상 「統率」가 가장 자연스럽다. 통솔; 지휘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2978","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域では良質な石炭を（　）する。","options":["略奪","志","年輪","産出"],"answer":"産出","explanationKo":"문맥상 「産出」가 가장 자연스럽다. 산출; 생산; 산출량라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2982","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請書の内容を本人確認書類と（　）した。","options":["お世辞","気配","照合","参議院"],"answer":"照合","explanationKo":"문맥상 「照合」가 가장 자연스럽다. 대조; 조회; 대조 확인라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0637","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n人口構成の変化は、地域の医療需要と（　）に関係している。","options":["健在","密接","質素","次いで"],"answer":"密接","explanationKo":"문맥상 「密接」가 가장 자연스럽다. 밀접; 긴밀함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0698","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n相手側が（　）な姿勢を崩さず、交渉は再び中断した。","options":["強硬","万能","達者","度々"],"answer":"強硬","explanationKo":"문맥상 「強硬」가 가장 자연스럽다. 강경; 타협하지 않는 태도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0408","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n道路が寸断されたため、被災地への救援（　）はヘリコプターで運ばれた。","options":["出品","富","雪崩","物資"],"answer":"物資","explanationKo":"문맥상 「物資」가 가장 자연스럽다. 물자; 물품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0410","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n入場時には身分証明書を（　）しているか確認される場合がある。","options":["偽造","適応","所持","産出"],"answer":"所持","explanationKo":"문맥상 「所持」가 가장 자연스럽다. 소지; 보유라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0411","prompt":"「過去の出来事・状態・現象などを、もう一度同じように現すこと。また、再び現れること。」という意味に最も近い語を選びなさい。","options":["志","再現","配給","略奪"],"answer":"再現","explanationKo":"「再現」의 핵심 의미는 재현; 다시 나타냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0416","prompt":"「社会や組織の中で地位が上がり、成功して名声や高い立場を得ること。」という意味に最も近い語を選びなさい。","options":["出世","果て","参議院","お世辞"],"answer":"出世","explanationKo":"「出世」의 핵심 의미는 출세; 승진하여 높은 지위에 오름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0418","prompt":"「続いていた作業・計画・活動などを途中で止めること。後で再開する場合にも用いる。」という意味に最も近い語を選びなさい。","options":["公","物資","視野","中断"],"answer":"中断","explanationKo":"「中断」의 핵심 의미는 중단; 일시 정지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0421","prompt":"「離れた場所や装置などの間に入って情報・放送・通信などをつなぐこと。また、現場から放送すること。」という意味に最も近い語を選びなさい。","options":["育ち","法学","中継","現行"],"answer":"中継","explanationKo":"「中継」의 핵심 의미는 중계; 중간에서 이어 줌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0425","prompt":"「物事を行う際に従うべき順序・方法・段階。」という意味に最も近い語を選びなさい。","options":["富","手順","特集","出品"],"answer":"手順","explanationKo":"「手順」의 핵심 의미는 절차; 순서; 작업 순서이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','grammar',1,'〜にして','{"pattern":"〜にして","meaningKo":"〜이면서; 〜에야","explanation":"〜にして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の経験者にして初めて気づく違いがある。","ko":"문맥에서 〜이면서; 〜에야의 의미로 쓰였다."},{"ja":"この困難な作業を一日で終えたのは、彼にして可能だった。","ko":"이 문장도 〜이면서; 〜에야의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','grammar',2,'〜にしてはじめて','{"pattern":"〜にしてはじめて","meaningKo":"〜에 이르러서야 비로소","explanation":"〜にしてはじめて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"三度目の試みにしてはじめて、装置は正常に動いた。","ko":"문맥에서 〜에 이르러서야 비로소의 의미로 쓰였다."},{"ja":"長年の実地調査にしてはじめて、問題の全体像が見えてきた。","ko":"이 문장도 〜에 이르러서야 비로소의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の経験者（　）初めて気づく違いがある。","options":["〜にして","〜に先駆けて","〜べくもない","〜ながらに"],"answer":"〜にして","explanationKo":"문맥상 〜이면서; 〜에야를 나타내는 「〜にして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n三度目の試み（　）、装置は正常に動いた。","options":["〜に先立って","〜んがため","〜をよそに","〜にしてはじめて"],"answer":"〜にしてはじめて","explanationKo":"문맥상 〜에 이르러서야 비로소를 나타내는 「〜にしてはじめて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n調査（　）、関係のない資料まで持ち出した。","options":["〜んばかりに","〜を限りに","〜にかこつけて","〜にこしたことはない"],"answer":"〜にかこつけて","explanationKo":"문맥상 〜을 구실로 삼아를 나타내는 「〜にかこつけて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-02','reading',1,'制度の公平さを測る','{"passage":"制度が公平かを検討することには、立場によって異なる負担を発見できることという意義がある。ただし、全員を同じに扱うだけでは格差が広がることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、必要と負担の違いも含めて比較することが重要である。","questions":[{"prompt":"「制度の公平さを測る」について筆者が重要だと述べることは何か。","options":["必要と負担の違いも含めて比較すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"必要と負担の違いも含めて比較すること","explanationKo":"본문의 결론은 必要と負担の違いも含めて比較すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["全員を同じに扱うだけでは格差が広がること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"全員を同じに扱うだけでは格差が広がること","explanationKo":"본문에서는 全員を同じに扱うだけでは格差が広がること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["立場によって異なる負担を発見できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"立場によって異なる負担を発見できること","explanationKo":"制度が公平かを検討すること에는 立場によって異なる負担を発見できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0440","prompt":"「到達」の読み方として最も適切なものを選びなさい。","options":["とうたつ","えん","げんこう","そだち"],"answer":"とうたつ","explanationKo":"「到達」는 「とうたつ」라고 읽는다. 뜻은 도달; 도착; 일정 수준에 이름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
