INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0448","prompt":"「暴動」の読み方として最も適切なものを選びなさい。","options":["りょうち","ひょうご","ぼうどう","かいてい"],"answer":"ぼうどう","explanationKo":"「暴動」는 「ぼうどう」라고 읽는다. 뜻은 폭동; 집단 소요이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0450","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度改正によって利用者の権利が（　）することがないよう、慎重な議論が必要だ。","options":["配給","後退","濫用","判定"],"answer":"後退","explanationKo":"문맥상 「後退」가 가장 자연스럽다. 후퇴; 퇴보; 뒤로 물러남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0451","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n将来のリーダーを（　）するため、若手社員向けの研修制度を見直した。","options":["育成","着手","分担","果て"],"answer":"育成","explanationKo":"문맥상 「育成」가 가장 자연스럽다. 육성; 양성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0455","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が上がるほど、専門知識だけでなく組織全体を見る力も求められる。","options":["一同","技能","閉口","役職"],"answer":"役職","explanationKo":"문맥상 「役職」가 가장 자연스럽다. 직책; 직위라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0457","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n契約に関する重要な（　）は、口頭だけでなく必ず文書に残したほうがよい。","options":["合議","再現","事柄","関税"],"answer":"事柄","explanationKo":"문맥상 「事柄」가 가장 자연스럽다. 사항; 일; 사안라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0459","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）だけで参加した会だったが、思いがけず有益な人脈ができた。","options":["特集","義理","産出","対決"],"answer":"義理","explanationKo":"문맥상 「義理」가 가장 자연스럽다. 의리; 사회적 도리; 인간관계상의 의무라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0465","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人確認に必要なので、（　）に身分証明書を用意してから手続きを始めてください。","options":["手元","対面","改訂","領地"],"answer":"手元","explanationKo":"문맥상 「手元」가 가장 자연스럽다. 손이 닿는 곳; 수중; 바로 곁라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0468","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n管理職になった以上、組織への影響力が大きいことを（　）して発言すべきだ。","options":["錯覚","濫用","判定","自覚"],"answer":"自覚","explanationKo":"문맥상 「自覚」가 가장 자연스럽다. 자각; 스스로 깨달음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0469","prompt":"「企業が資金不足などによって事業を続けられなくなり、経営が破綻すること。」という意味に最も近い語を選びなさい。","options":["着手","分担","倒産","育成"],"answer":"倒産","explanationKo":"「倒産」의 핵심 의미는 도산; 기업 파산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0477","prompt":"「新しい発明について、一定期間その発明を独占的に利用できる権利を国が認める制度。また、その権利。」という意味に最も近い語を選びなさい。","options":["技能","特許","獲物","一同"],"answer":"特許","explanationKo":"「特許」의 핵심 의미는 특허; 특허권이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0478","prompt":"「王・皇帝など、君主制の国家で原則として国家の元首となる人物。」という意味に最も近い語を選びなさい。","options":["君主","心得","関税","合議"],"answer":"君主","explanationKo":"「君主」의 핵심 의미는 군주; 왕이나 황제이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0479","prompt":"「大きな成功・地位・権力などを得ようとする強い望み。文脈によって肯定的にも否定的にも使う。」という意味に最も近い語を選びなさい。","options":["返還","産出","対決","野心"],"answer":"野心","explanationKo":"「野心」의 핵심 의미는 야심; 큰 목표를 이루려는 욕망이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0484","prompt":"「現在実施・使用されている制度・規則・方式など。」という意味に最も近い語を選びなさい。","options":["対面","改訂","現行","酸化"],"answer":"現行","explanationKo":"「現行」의 핵심 의미는 현행; 현재 시행 중인 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','grammar',1,'〜にかこつけて','{"pattern":"〜にかこつけて","meaningKo":"〜을 구실로 삼아","explanation":"〜にかこつけて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"出張にかこつけて、以前から訪れたかった町へ行った。","ko":"문맥에서 〜을 구실로 삼아의 의미로 쓰였다."},{"ja":"調査にかこつけて、関係のない資料まで持ち出した。","ko":"이 문장도 〜을 구실로 삼아의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','grammar',2,'〜に則って','{"pattern":"〜に則って","meaningKo":"〜에 따라; 〜에 입각해","explanation":"〜に則って는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"社内規程に則って、申請を処理してください。","ko":"문맥에서 〜에 따라; 〜에 입각해의 의미로 쓰였다."},{"ja":"法律に則って、公正に手続きを進める必要がある。","ko":"이 문장도 〜에 따라; 〜에 입각해의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n出張（　）、以前から訪れたかった町へ行った。","options":["〜にこしたことはない","〜んばかりに","〜を限りに","〜にかこつけて"],"answer":"〜にかこつけて","explanationKo":"문맥상 〜을 구실로 삼아를 나타내는 「〜にかこつけて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n社内規程（　）、申請を処理してください。","options":["〜とばかりに","〜にかたくない","〜に則って","〜には及ばない"],"answer":"〜に則って","explanationKo":"문맥상 〜에 따라; 〜에 입각해를 나타내는 「〜に則って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n社会通念（　）、その判断が妥当か考えるべきだ。","options":["〜にひきかえ","〜に照らして","〜まじき","〜と相まって"],"answer":"〜に照らして","explanationKo":"문맥상 〜에 비추어를 나타내는 「〜に照らして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-03','reading',1,'余裕を設計に含める','{"passage":"計画に時間の余裕を含めることには、予想外の変更にも対応しやすくなることという意義がある。ただし、余裕を目的なく消費すると締切だけが遅れることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、どの不確実性に備える時間かを明示することが重要である。","questions":[{"prompt":"「余裕を設計に含める」について筆者が重要だと述べることは何か。","options":["どの不確実性に備える時間かを明示すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"どの不確実性に備える時間かを明示すること","explanationKo":"본문의 결론은 どの不確実性に備える時間かを明示すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["余裕を目的なく消費すると締切だけが遅れること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"余裕を目的なく消費すると締切だけが遅れること","explanationKo":"본문에서는 余裕を目的なく消費すると締切だけが遅れること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["予想外の変更にも対応しやすくなること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"予想外の変更にも対応しやすくなること","explanationKo":"計画に時間の余裕を含めること에는 予想外の変更にも対応しやすくなること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0497","prompt":"「判定」の読み方として最も適切なものを選びなさい。","options":["とっきょ","はんてい","りょうかい","たすうけつ"],"answer":"はんてい","explanationKo":"「判定」는 「はんてい」라고 읽는다. 뜻은 판정; 판단하여 결정함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
