INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0510","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n身分証明書を（　）して他人になりすました疑いで男が逮捕された。","options":["偽造","補給","畜産","核"],"answer":"偽造","explanationKo":"문맥상 「偽造」가 가장 자연스럽다. 위조; 가짜를 진짜처럼 만듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0513","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n突然の発表に社員は（　）したが、責任者の説明を聞いて次第に落ち着いた。","options":["インフレ","領海","多数決","動揺"],"answer":"動揺","explanationKo":"문맥상 「動揺」가 가장 자연스럽다. 동요; 흔들림; 평정심을 잃음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0516","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n総会では経営体制の見直しを求める（　）が賛成多数で採択された。","options":["事柄","平行","決議","効き目"],"answer":"決議","explanationKo":"문맥상 「決議」가 가장 자연스럽다. 결의; 회의에서 의결함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0523","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n緊急時には情報（　）の経路を一本化し、誤った指示が広がらないようにする。","options":["財源","伝達","主題","待ち合わせ"],"answer":"伝達","explanationKo":"문맥상 「伝達」가 가장 자연스럽다. 전달; 전달함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0524","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの制度は当時の社会状況の（　）であり、現在の事情には合わない部分もある。","options":["産物","講習","旅券","刑"],"answer":"産物","explanationKo":"문맥상 「産物」가 가장 자연스럽다. 산물; 생산물; 결과물라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0534","prompt":"「他人の支配・援助に過度に頼らず、自分の力と責任で生活・行動すること。」という意味に最も近い語を選びなさい。","options":["聴講","独裁","創立","自立"],"answer":"自立","explanationKo":"「自立」의 핵심 의미는 자립; 스스로 생활함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0539","prompt":"「制度・組織・社会などを、従来とは大きく異なる形へ根本的に変えること。」という意味に最も近い語を選びなさい。","options":["補給","畜産","変革","自立"],"answer":"変革","explanationKo":"「変革」의 핵심 의미는 변혁; 근본적인 변화이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0546","prompt":"「文章・作品・研究・議論などで中心となる題目や考え。」という意味に最も近い語を選びなさい。","options":["好評","主題","炭素","比率"],"answer":"主題","explanationKo":"「主題」의 핵심 의미는 주제; 중심이 되는 문제이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0547","prompt":"「銀行に対して、記載した金額を所持人などに支払うよう指図する有価証券。」という意味に最も近い語を選びなさい。","options":["小切手","議題","採掘","濫用"],"answer":"小切手","explanationKo":"「小切手」의 핵심 의미는 수표이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0549","prompt":"「蓄えられていた物質・エネルギー・資金・在庫などを外へ出すこと。」という意味に最も近い語を選びなさい。","options":["動向","主題","待ち合わせ","放出"],"answer":"放出","explanationKo":"「放出」의 핵심 의미는 방출; 내보냄; 풀어냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','grammar',1,'〜に照らして','{"pattern":"〜に照らして","meaningKo":"〜에 비추어","explanation":"〜に照らして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"過去の事例に照らして、今回の対応を検討する。","ko":"문맥에서 〜에 비추어의 의미로 쓰였다."},{"ja":"社会通念に照らして、その判断が妥当か考えるべきだ。","ko":"이 문장도 〜에 비추어의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','grammar',2,'〜に先駆けて','{"pattern":"〜に先駆けて","meaningKo":"〜에 앞서","explanation":"〜に先駆けて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"全国発売に先駆けて、試作品が公開された。","ko":"문맥에서 〜에 앞서의 의미로 쓰였다."},{"ja":"制度の導入に先駆けて、職員向けの講習を行った。","ko":"이 문장도 〜에 앞서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n過去の事例（　）、今回の対応を検討する。","options":["〜と相まって","〜にひきかえ","〜に照らして","〜まじき"],"answer":"〜に照らして","explanationKo":"문맥상 〜에 비추어를 나타내는 「〜に照らして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n全国発売（　）、試作品が公開された。","options":["〜に至って","〜に先駆けて","〜べく","〜ないではおかない"],"answer":"〜に先駆けて","explanationKo":"문맥상 〜에 앞서를 나타내는 「〜に先駆けて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n契約の締結（　）、条件を改めて確認した。","options":["〜に先立って","〜べくもない","〜ないではすまない","〜に至っては"],"answer":"〜に先立って","explanationKo":"문맥상 〜에 앞서를 나타내는 「〜に先立って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-04','reading',1,'小さな兆候を読む','{"passage":"小さな変化の兆候を観察することには、大きな問題になる前に対応を始められることという意義がある。ただし、一度の変化だけで原因を断定すると誤ることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、複数の記録と現場の説明を照合することが重要である。","questions":[{"prompt":"「小さな兆候を読む」について筆者が重要だと述べることは何か。","options":["複数の記録と現場の説明を照合すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"複数の記録と現場の説明を照合すること","explanationKo":"본문의 결론은 複数の記録と現場の説明を照合すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["一度の変化だけで原因を断定すると誤ること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"一度の変化だけで原因を断定すると誤ること","explanationKo":"본문에서는 一度の変化だけで原因を断定すると誤ること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["大きな問題になる前に対応を始められること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"大きな問題になる前に対応を始められること","explanationKo":"小さな変化の兆候を観察すること에는 大きな問題になる前に対応を始められること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0557","prompt":"「返済」の読み方として最も適切なものを選びなさい。","options":["なだれ","ききめ","へんさい","とみ"],"answer":"へんさい","explanationKo":"「返済」는 「へんさい」라고 읽는다. 뜻은 상환; 빌린 돈이나 빚을 갚음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0558","prompt":"「総会」の読み方として最も適切なものを選びなさい。","options":["いくせい","そうかい","だったい","ボイコット"],"answer":"そうかい","explanationKo":"「総会」는 「そうかい」라고 읽는다. 뜻은 총회; 전체 구성원이 모이는 회의이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0559","prompt":"「交付」の読み方として最も適切なものを選びなさい。","options":["こうふ","いぎ","しゃこう","こせき"],"answer":"こうふ","explanationKo":"「交付」는 「こうふ」라고 읽는다. 뜻은 교부; 공적 문서·증서 등을 내줌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0560","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害復興を支援する（　）には、国内外から多くの寄付が寄せられた。","options":["公認","根底","切っ掛け","基金"],"answer":"基金","explanationKo":"문맥상 「基金」가 가장 자연스럽다. 기금; 특정 목적을 위해 마련한 자금라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0561","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予算が正式に承認され次第、新システムの開発に（　）する予定だ。","options":["中断","自立","着手","兼業"],"answer":"着手","explanationKo":"문맥상 「着手」가 가장 자연스럽다. 착수; 일을 시작함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0563","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n研究成果をまとめた報告書が来月（　）される予定だ。","options":["分配","刊行","動揺","共感"],"answer":"刊行","explanationKo":"문맥상 「刊行」가 가장 자연스럽다. 간행; 출판하여 세상에 냄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0564","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n重要な契約については、オンラインではなく（　）で説明する方針になった。","options":["対面","出品","富","雪崩"],"answer":"対面","explanationKo":"문맥상 「対面」가 가장 자연스럽다. 대면; 직접 얼굴을 마주함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0567","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害直後は飲料水や食料の（　）が限られ、長い列ができた。","options":["標語","係り","動向","配給"],"answer":"配給","explanationKo":"문맥상 「配給」가 가장 자연스럽다. 배급; 정해진 기준에 따라 나누어 줌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0571","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n政府は非常事態を（　）し、住民に不要不急の外出を控えるよう求めた。","options":["異議","社交","布告","連盟"],"answer":"布告","explanationKo":"문맥상 「布告」가 가장 자연스럽다. 포고; 공식적으로 널리 알림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0572","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n睡眠不足は体の（　）機能だけでなく、判断力にも影響を与える。","options":["根底","生理","自立","公認"],"answer":"生理","explanationKo":"문맥상 「生理」가 가장 자연스럽다. 생리; 생리 기능; 월경라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0574","prompt":"「新聞・雑誌・番組などで、特定のテーマを集中的に取り上げて構成すること。また、その記事・番組。」という意味に最も近い語を選びなさい。","options":["特集","結晶","兼業","中断"],"answer":"特集","explanationKo":"「特集」의 핵심 의미는 특집; 특정 주제를 집중적으로 다룸이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0576","prompt":"「環境・条件・状況などに合うように、自分の状態や行動を変えてなじむこと。」という意味に最も近い語を選びなさい。","options":["所持","動揺","共感","適応"],"answer":"適応","explanationKo":"「適応」의 핵심 의미는 적응; 환경·조건에 맞게 변화함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0577","prompt":"「生物の体を切り開いて内部の構造を調べること。転じて、物事を細かく分析する意味でも使う。」という意味に最も近い語を選びなさい。","options":["出品","富","解剖","布告"],"answer":"解剖","explanationKo":"「解剖」의 핵심 의미는 해부; 내부 구조를 조사함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0578","prompt":"「経験・失敗・出来事などから得られる、今後の行動の戒めや指針となる教え。」という意味に最も近い語を選びなさい。","options":["脱退","教訓","中枢","実情"],"answer":"教訓","explanationKo":"「教訓」의 핵심 의미는 교훈; 경험에서 얻는 가르침이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0580","prompt":"「他人の感情・考え・経験などを理解し、自分も同じように感じること。」という意味に最も近い語を選びなさい。","options":["共感","躾","連盟","異議"],"answer":"共感","explanationKo":"「共感」의 핵심 의미는 공감; 상대의 감정·생각을 함께 느낌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','grammar',1,'〜に先立って','{"pattern":"〜に先立って","meaningKo":"〜에 앞서","explanation":"〜に先立って는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"工事開始に先立って、周辺住民への説明会を開く。","ko":"문맥에서 〜에 앞서의 의미로 쓰였다."},{"ja":"契約の締結に先立って、条件を改めて確認した。","ko":"이 문장도 〜에 앞서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','grammar',2,'〜にこしたことはない','{"pattern":"〜にこしたことはない","meaningKo":"〜보다 좋은 것은 없다","explanation":"〜にこしたことはない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"早めに準備するにこしたことはない。","ko":"문맥에서 〜보다 좋은 것은 없다의 의미로 쓰였다."},{"ja":"資料は分かりやすいにこしたことはない。","ko":"이 문장도 〜보다 좋은 것은 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n工事開始（　）、周辺住民への説明会を開く。","options":["〜に至っては","〜に先立って","〜べくもない","〜ないではすまない"],"answer":"〜に先立って","explanationKo":"문맥상 〜에 앞서를 나타내는 「〜に先立って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n早めに準備する（　）。","options":["〜にこしたことはない","〜んがため","〜ともなく","〜に至っても"],"answer":"〜にこしたことはない","explanationKo":"문맥상 〜보다 좋은 것은 없다를 나타내는 「〜にこしたことはない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nまだ時間はあるから、慌てる（　）。","options":["〜んばかりに","〜ながらに","〜にあって","〜には及ばない"],"answer":"〜には及ばない","explanationKo":"문맥상 〜할 필요는 없다를 나타내는 「〜には及ばない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-05','reading',1,'役割を引き継ぐ準備','{"passage":"担当業務を他者へ引き継ぐことには、担当者が変わっても業務を継続できることという意義がある。ただし、操作手順だけでは判断の理由が伝わらないこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、例外時の考え方と確認先も残すことが重要である。","questions":[{"prompt":"「役割を引き継ぐ準備」について筆者が重要だと述べることは何か。","options":["例外時の考え方と確認先も残すこと","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"例外時の考え方と確認先も残すこと","explanationKo":"본문의 결론은 例外時の考え方と確認先も残すこと 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["操作手順だけでは判断の理由が伝わらないこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"操作手順だけでは判断の理由が伝わらないこと","explanationKo":"본문에서는 操作手順だけでは判断の理由が伝わらないこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当者が変わっても業務を継続できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"担当者が変わっても業務を継続できること","explanationKo":"担当業務を他者へ引き継ぐこと에는 担当者が変わっても業務を継続できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0595","prompt":"「鉱山」の読み方として最も適切なものを選びなさい。","options":["いぎ","ちゅうすう","じつじょう","こうざん"],"answer":"こうざん","explanationKo":"「鉱山」는 「こうざん」라고 읽는다. 뜻은 광산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0598","prompt":"「社交」の読み方として最も適切なものを選びなさい。","options":["けいしゃ","こんけつ","しゃこう","ふきょう"],"answer":"しゃこう","explanationKo":"「社交」는 「しゃこう」라고 읽는다. 뜻은 사교; 사회적인 교제이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0599","prompt":"「中枢」の読み方として最も適切なものを選びなさい。","options":["じりつ","ちゅうすう","したしらべ","ちゅうだん"],"answer":"ちゅうすう","explanationKo":"「中枢」는 「ちゅうすう」라고 읽는다. 뜻은 중추; 핵심부; 중심 기능을 맡는 부분이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0606","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地域の（　）に合った建築様式が、長い年月をかけて発達してきた。","options":["風土","動揺","解剖","加入"],"answer":"風土","explanationKo":"문맥상 「風土」가 가장 자연스럽다. 풍토; 지역의 자연·생활 환경과 특성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0607","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅前は混雑するので、（　）場所を改札の外に変更した。","options":["選考","不動産","文化財","待ち合わせ"],"answer":"待ち合わせ","explanationKo":"문맥상 「待ち合わせ」가 가장 자연스럽다. 약속 장소에서 만남; 만나기로 한 약속라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0608","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの大会で使用できるのは、競技団体が（　）した用具に限られる。","options":["自主","布告","公認","統率"],"answer":"公認","explanationKo":"문맥상 「公認」가 가장 자연스럽다. 공인; 공식적으로 인정함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0609","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）は証拠を精査したうえで、被疑者を起訴するかどうか判断した。","options":["社交","検事","連盟","異議"],"answer":"検事","explanationKo":"문맥상 「検事」가 가장 자연스럽다. 검사; 형사 사건을 수사·기소하는 법률 공무원라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0610","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n古い絵画は、当時の庶民の生活や（　）を知る貴重な資料になる。","options":["風俗","慣習","不況","傾斜"],"answer":"風俗","explanationKo":"문맥상 「風俗」가 가장 자연스럽다. 풍속; 사회의 생활 습관·풍습라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0614","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n各部署の情報を（　）的に結び付けることで、組織全体の判断を速くできる。","options":["目録","下調べ","中断","有機"],"answer":"有機","explanationKo":"문맥상 「有機」가 가장 자연스럽다. 유기; 생물·탄소 화합물과 관련됨; 유기적으로 연결됨라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0618","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n売上に占める海外事業の（　）が、この五年間で大きく上昇した。","options":["動揺","解剖","比率","所持"],"answer":"比率","explanationKo":"문맥상 「比率」가 가장 자연스럽다. 비율; 기준량에 대한 다른 양의 비라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0619","prompt":"「仕事・予算・数量・役割などを分け、それぞれの人や対象にあてること。また、その分。」という意味に最も近い語を選びなさい。","options":["不動産","割り当て","布告","選考"],"answer":"割り当て","explanationKo":"「割り当て」의 핵심 의미는 할당; 배정; 나누어 맡김이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0620","prompt":"「よい行い・成果・努力などをほめ、その報いとして与える金品や利益。」という意味に最も近い語を選びなさい。","options":["褒美","策","衆議院","茶の湯"],"answer":"褒美","explanationKo":"「褒美」의 핵심 의미는 상; 포상; 잘한 일에 주는 보상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0621","prompt":"「物事を行う上で知っておくべき知識・心構え・注意点。」という意味に最も近い語を選びなさい。","options":["構え","連盟","異議","心得"],"answer":"心得","explanationKo":"「心得」의 핵심 의미는 마음가짐; 알아두어야 할 사항; 기본 지식이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0622","prompt":"「不足した物資・燃料・食料などを追加して供給すること。」という意味に最も近い語を選びなさい。","options":["年鑑","玄人","補給","樹立"],"answer":"補給","explanationKo":"「補給」의 핵심 의미는 보급; 보충 공급이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0623","prompt":"「政権を担当している政党。」という意味に最も近い語を選びなさい。","options":["下調べ","与党","法学","目録"],"answer":"与党","explanationKo":"「与党」의 핵심 의미는 여당; 집권당이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','grammar',1,'〜には及ばない','{"pattern":"〜には及ばない","meaningKo":"〜할 필요는 없다","explanation":"〜には及ばない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"簡単な確認なので、専門家に頼むには及ばない。","ko":"문맥에서 〜할 필요는 없다의 의미로 쓰였다."},{"ja":"まだ時間はあるから、慌てるには及ばない。","ko":"이 문장도 〜할 필요는 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','grammar',2,'〜まじき','{"pattern":"〜まじき","meaningKo":"〜로서는 해서는 안 될","explanation":"〜まじき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"これは指導者にあるまじき発言だ。","ko":"문맥에서 〜로서는 해서는 안 될의 의미로 쓰였다."},{"ja":"資料の改ざんは研究者にあるまじき行為である。","ko":"이 문장도 〜로서는 해서는 안 될의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n簡単な確認なので、専門家に頼む（　）。","options":["〜には及ばない","〜んばかりに","〜ながらに","〜にあって"],"answer":"〜には及ばない","explanationKo":"문맥상 〜할 필요는 없다를 나타내는 「〜には及ばない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこれは指導者にある（　）発言だ。","options":["〜とばかりに","〜をよそに","〜にして","〜まじき"],"answer":"〜まじき","explanationKo":"문맥상 〜로서는 해서는 안 될를 나타내는 「〜まじき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n真相を明らかにす（　）、追加調査が行われた。","options":["〜を限りに","〜にしてはじめて","〜べく","〜と相まって"],"answer":"〜べく","explanationKo":"문맥상 〜하기 위해를 나타내는 「〜べく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-06','reading',1,'合意後の確認','{"passage":"合意した内容を後から確認することには、前提の変化に合わせて判断を修正できることという意義がある。ただし、合意を絶対視すると新しい問題を見落とすこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、見直す条件と時期をあらかじめ定めることが重要である。","questions":[{"prompt":"「合意後の確認」について筆者が重要だと述べることは何か。","options":["見直す条件と時期をあらかじめ定めること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"見直す条件と時期をあらかじめ定めること","explanationKo":"본문의 결론은 見直す条件と時期をあらかじめ定めること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["合意を絶対視すると新しい問題を見落とすこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"合意を絶対視すると新しい問題を見落とすこと","explanationKo":"본문에서는 合意を絶対視すると新しい問題を見落とすこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["前提の変化に合わせて判断を修正できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"前提の変化に合わせて判断を修正できること","explanationKo":"合意した内容を後から確認すること에는 前提の変化に合わせて判断を修正できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0632","prompt":"「理屈」の読み方として最も適切なものを選びなさい。","options":["りくつ","ざだんかい","めいぼ","かんしゅう"],"answer":"りくつ","explanationKo":"「理屈」는 「りくつ」라고 읽는다. 뜻은 이치; 논리; 이론상의 설명이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
