INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0639","prompt":"「戸籍」の読み方として最も適切なものを選びなさい。","options":["ストライキ","しょじ","こせき","あいま"],"answer":"こせき","explanationKo":"「戸籍」는 「こせき」라고 읽는다. 뜻은 호적; 가족관계 등록부이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0640","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n委員会は事故の原因だけでなく、管理責任についても厳しく（　）した。","options":["割り当て","追及","手元","総会"],"answer":"追及","explanationKo":"문맥상 「追及」가 가장 자연스럽다. 추궁; 책임을 따져 물음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0642","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自治体の担当者が工場を（　）し、安全対策の実施状況を確認した。","options":["視察","風俗","必然","失格"],"answer":"視察","explanationKo":"문맥상 「視察」가 가장 자연스럽다. 시찰; 현장 점검 방문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0645","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n両国は長年の交渉を経て、正式な外交関係を（　）した。","options":["回覧","橋渡し","倒産","樹立"],"answer":"樹立","explanationKo":"문맥상 「樹立」가 가장 자연스럽다. 수립; 세움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0647","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度を改める前に、現場の（　）を詳しく調査する必要がある。","options":["座談会","名簿","実情","好況"],"answer":"実情","explanationKo":"문맥상 「実情」가 가장 자연스럽다. 실정; 실제 사정라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0648","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n感染症の拡大を防ぐため、（　）の移動が一時的に制限された。","options":["与党","家畜","野心","教訓"],"answer":"家畜","explanationKo":"문맥상 「家畜」가 가장 자연스럽다. 가축라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0649","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新たな福祉制度を導入するには、安定した（　）を確保しなければならない。","options":["財源","割り当て","合間","ストライキ"],"answer":"財源","explanationKo":"문맥상 「財源」가 가장 자연스럽다. 재원; 자금의 출처라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0651","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n次回の会議では、予算配分と人員配置を主要な（　）として扱う。","options":["束縛","統率","自主","議題"],"answer":"議題","explanationKo":"문맥상 「議題」가 가장 자연스럽다. 의제; 회의 안건라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0654","prompt":"「原因・条件から見て、そうなる以外にあり得ないこと。」という意味に最も近い語を選びなさい。","options":["刊行","蓄積","必然","倒産"],"answer":"必然","explanationKo":"「必然」의 핵심 의미는 필연; 반드시 그렇게 됨이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0657","prompt":"「仕事・責任・費用などを複数の人や組織で分けて受け持つこと。」という意味に最も近い語を選びなさい。","options":["橋渡し","分担","家畜","回覧"],"answer":"分担","explanationKo":"「分担」의 핵심 의미는 분담; 나누어 맡음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0658","prompt":"「まだ知られていないこと、または経験したことがないこと。」という意味に最も近い語を選びなさい。","options":["未知","闇","好況","座談会"],"answer":"未知","explanationKo":"「未知」의 핵심 의미는 미지; 아직 알려지지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0659","prompt":"「多くの人から良い評価を受けること、またその評価。」という意味に最も近い語を選びなさい。","options":["議事堂","野心","教訓","好評"],"answer":"好評","explanationKo":"「好評」의 핵심 의미는 호평; 좋은 평가이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0660","prompt":"「知識・経験・資金・データなどが少しずつたまり、増えていくこと。また、ためること。」という意味に最も近い語を選びなさい。","options":["切っ掛け","不評","蓄積","根底"],"answer":"蓄積","explanationKo":"「蓄積」의 핵심 의미는 축적; 쌓임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','grammar',1,'〜べく','{"pattern":"〜べく","meaningKo":"〜하기 위해","explanation":"〜べく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"問題を解決すべく、関係者が協議を重ねた。","ko":"문맥에서 〜하기 위해의 의미로 쓰였다."},{"ja":"真相を明らかにすべく、追加調査が行われた。","ko":"이 문장도 〜하기 위해의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','grammar',2,'〜べくもない','{"pattern":"〜べくもない","meaningKo":"도저히 〜할 수 없다","explanation":"〜べくもない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"当時の混乱は、今となっては知るべくもない。","ko":"문맥에서 도저히 〜할 수 없다의 의미로 쓰였다."},{"ja":"結果を事前に予測すべくもない状況だった。","ko":"이 문장도 도저히 〜할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n問題を解決す（　）、関係者が協議を重ねた。","options":["〜と相まって","〜を限りに","〜にしてはじめて","〜べく"],"answer":"〜べく","explanationKo":"문맥상 〜하기 위해를 나타내는 「〜べく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n当時の混乱は、今となっては知る（　）。","options":["〜にかたくない","〜にかこつけて","〜べくもない","〜ないではおかない"],"answer":"〜べくもない","explanationKo":"문맥상 도저히 〜할 수 없다를 나타내는 「〜べくもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n真実を明らかにせ（　）、記録を丹念に調べた。","options":["〜に則って","〜んがため","〜ないではすまない","〜にひきかえ"],"answer":"〜んがため","explanationKo":"문맥상 〜하기 위해를 나타내는 「〜んがため」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-07','reading',1,'評価指標の限界','{"passage":"成果を数値の指標で評価することには、変化を共通の基準で比較しやすくなることという意義がある。ただし、測りやすい結果だけが目的になることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、指標が捉えない価値も言葉で確認することが重要である。","questions":[{"prompt":"「評価指標の限界」について筆者が重要だと述べることは何か。","options":["指標が捉えない価値も言葉で確認すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"指標が捉えない価値も言葉で確認すること","explanationKo":"본문의 결론은 指標が捉えない価値も言葉で確認すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["測りやすい結果だけが目的になること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"測りやすい結果だけが目的になること","explanationKo":"본문에서는 測りやすい結果だけが目的になること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["変化を共通の基準で比較しやすくなること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"変化を共通の基準で比較しやすくなること","explanationKo":"成果を数値の指標で評価すること에는 変化を共通の基準で比較しやすくなること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0674","prompt":"「配分」の読み方として最も適切なものを選びなさい。","options":["ほそく","はいぶん","きゅうさい","ほうしゅつ"],"answer":"はいぶん","explanationKo":"「配分」는 「はいぶん」라고 읽는다. 뜻은 배분; 몫을 나눔이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
