INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0692","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が引き下げられれば、輸入品の価格にも影響が出る可能性がある。","options":["にも拘らず","倒産","関税","錯覚"],"answer":"関税","explanationKo":"문맥상 「関税」가 가장 자연스럽다. 관세라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0693","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利益をどのように（　）するかは、共同事業を始める前に決めておくべきだ。","options":["家畜","分配","産物","風土"],"answer":"分配","explanationKo":"문맥상 「分配」가 가장 자연스럽다. 분배; 나누어 배정함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0694","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの受賞作は、研究者たちの長年にわたる努力の（　）だ。","options":["結晶","補足","物議","闇"],"answer":"結晶","explanationKo":"문맥상 「結晶」가 가장 자연스럽다. 결정; 결정체라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0696","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n博物館は所蔵資料の（　）をデジタル化し、一般公開を始めた。","options":["邸宅","余暇","議事堂","目録"],"answer":"目録","explanationKo":"문맥상 「目録」가 가장 자연스럽다. 목록; 목록집라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0728","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの資格は大学卒業と（　）の知識を証明するものではない。","options":["公然","ほっと","同等","手軽"],"answer":"同等","explanationKo":"문맥상 「同等」가 가장 자연스럽다. 동등; 같은 수준라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0731","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n再生可能エネルギーは今後さらに成長が期待される（　）な分野だ。","options":["元来","有望","最早","単一"],"answer":"有望","explanationKo":"문맥상 「有望」가 가장 자연스럽다. 유망함; 장래성이 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0752","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n派手さはないが、素材の味を生かした（　）な料理が人気だ。","options":["素朴","気まぐれ","取り分け","簡素"],"answer":"素朴","explanationKo":"문맥상 「素朴」가 가장 자연스럽다. 소박함; 꾸밈없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0754","prompt":"「もともと。初めからそうであることを表す語。」という意味に最も近い語を選びなさい。","options":["一気","自在","手遅れ","元来"],"answer":"元来","explanationKo":"「元来」의 핵심 의미는 원래; 본래이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0767","prompt":"「数量・状態・程度などが中途半端で、まとまりや十分さに欠けるさま。」という意味に最も近い語を選びなさい。","options":["万能","達者","半端","一気"],"answer":"半端","explanationKo":"「半端」의 핵심 의미는 어중간함; 불완전함; 중途반단이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0777","prompt":"「思いどおりに自由に扱ったり動かしたりできるさま。」という意味に最も近い語を選びなさい。","options":["気軽","自在","手遅れ","益々"],"answer":"自在","explanationKo":"「自在」의 핵심 의미는 자유자재; 마음대로 다룸이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0782","prompt":"「深く心配したり遠慮したりせず、楽な気持ちで行動できるさま。」という意味に最も近い語を選びなさい。","options":["気軽","有望","密か","正に"],"answer":"気軽","explanationKo":"「気軽」의 핵심 의미는 가벼운 마음; 부담 없음; 편하게이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0785","prompt":"「隠すことなく、周囲に知られる形ではっきり行うさま。」という意味に最も近い語を選びなさい。","options":["不服","連日","密接","公然"],"answer":"公然","explanationKo":"「公然」의 핵심 의미는 공공연히; 숨김없이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','grammar',1,'〜んがため','{"pattern":"〜んがため","meaningKo":"〜하기 위해","explanation":"〜んがため는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"目標を達成せんがため、彼は努力を重ねた。","ko":"문맥에서 〜하기 위해의 의미로 쓰였다."},{"ja":"真実を明らかにせんがため、記録を丹念に調べた。","ko":"이 문장도 〜하기 위해의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','grammar',2,'〜んばかりに','{"pattern":"〜んばかりに","meaningKo":"금방이라도 〜할 듯이","explanation":"〜んばかりに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は泣かんばかりに謝罪した。","ko":"문맥에서 금방이라도 〜할 듯이의 의미로 쓰였다."},{"ja":"観客は割れんばかりに拍手を送った。","ko":"이 문장도 금방이라도 〜할 듯이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n目標を達成せ（　）、彼は努力を重ねた。","options":["〜にひきかえ","〜に則って","〜んがため","〜ないではすまない"],"answer":"〜んがため","explanationKo":"문맥상 〜하기 위해를 나타내는 「〜んがため」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は泣か（　）謝罪した。","options":["〜に照らして","〜んばかりに","〜ともなく","〜に至って"],"answer":"〜んばかりに","explanationKo":"문맥상 금방이라도 〜할 듯이를 나타내는 「〜んばかりに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今が好機だ（　）、各社が市場へ参入した。","options":["〜とばかりに","〜ながらに","〜に至っては","〜に先駆けて"],"answer":"〜とばかりに","explanationKo":"문맥상 마치 〜라는 듯이를 나타내는 「〜とばかりに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-08','reading',1,'情報を減らす判断','{"passage":"伝える情報を整理して減らすことには、受け手が重要な点に集中できることという意義がある。ただし、根拠まで省くと判断の妥当性を確かめられないこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、結論と根拠を残して重複だけを除くことが重要である。","questions":[{"prompt":"「情報を減らす判断」について筆者が重要だと述べることは何か。","options":["結論と根拠を残して重複だけを除くこと","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"結論と根拠を残して重複だけを除くこと","explanationKo":"본문의 결론은 結論と根拠を残して重複だけを除くこと 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["根拠まで省くと判断の妥当性を確かめられないこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"根拠まで省くと判断の妥当性を確かめられないこと","explanationKo":"본문에서는 根拠まで省くと判断の妥当性を確かめられないこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["受け手が重要な点に集中できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"受け手が重要な点に集中できること","explanationKo":"伝える情報を整理して減らすこと에는 受け手が重要な点に集中できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0976","prompt":"「記す」の読み方として最も適切なものを選びなさい。","options":["とどまる","つよめる","しるす","まさる"],"answer":"しるす","explanationKo":"「記す」는 「しるす」라고 읽는다. 뜻은 기록하다; 적다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
