INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0850","prompt":"「単一」の読み方として最も適切なものを選びなさい。","options":["たんいつ","じざい","ゆうび","じゃっかん"],"answer":"たんいつ","explanationKo":"「単一」는 「たんいつ」라고 읽는다. 뜻은 단일; 하나뿐임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0857","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nスマートフォンで（　）に予約できるため、利用者が急増した。","options":["正に","半端","完璧","手軽"],"answer":"手軽","explanationKo":"문맥상 「手軽」가 가장 자연스럽다. 간편함; 손쉽게 할 수 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0862","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n判定に（　）がある場合は、所定の手続きで再審査を申し立てられる。","options":["難い","素朴","不服","臆病"],"answer":"不服","explanationKo":"문맥상 「不服」가 가장 자연스럽다. 불복; 불만라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0863","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n詳細な日程は（　）正式に発表される予定だ。","options":["小柄","近々","公然","即ち"],"answer":"近々","explanationKo":"문맥상 「近々」가 가장 자연스럽다. 조만간; 머지않아라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0891","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n猛暑が（　）続き、熱中症への注意が呼びかけられている。","options":["連日","単一","元来","態々"],"answer":"連日","explanationKo":"문맥상 「連日」가 가장 자연스럽다. 연일; 여러 날 계속라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0895","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼女は（　）だが、長距離を走る体力には非常に優れている。","options":["手軽","近々","態々","小柄"],"answer":"小柄","explanationKo":"문맥상 「小柄」가 가장 자연스럽다. 작은 체구; 몸집이 작음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0898","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n作業は（　）終わったので、残るのは最終確認だけだ。","options":["最早","健在","大方","達者"],"answer":"大方","explanationKo":"문맥상 「大方」가 가장 자연스럽다. 대체로; 대부분; 대강라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0912","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な時期ほど、優先順位を決めて仕事を整理する必要がある。","options":["簡素","多忙","柔軟","最早"],"answer":"多忙","explanationKo":"문맥상 「多忙」가 가장 자연스럽다. 다망; 매우 바쁨라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0931","prompt":"「他と比べて明らかに程度が上であるさま。また、きっぱりとしたさま。」という意味に最も近い語を選びなさい。","options":["断然","若干","気軽","完璧"],"answer":"断然","explanationKo":"「断然」의 핵심 의미는 단연; 압도적으로이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0946","prompt":"「変化が少なく、同じような状態が続いて面白みに欠けるさま。」という意味に最も近い語を選びなさい。","options":["若干","万能","質素","単調"],"answer":"単調","explanationKo":"「単調」의 핵심 의미는 단조로움; 변화가 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0970","prompt":"「ある物事に別の物事が付随して起こる。また、人などを連れて行く。」という意味に最も近い語を選びなさい。","options":["尽きる","止める","伴う","引き起こす"],"answer":"伴う","explanationKo":"「伴う」의 핵심 의미는 수반하다; 동반하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0972","prompt":"「程度が非常に高いことを表す語。」という意味に最も近い語を選びなさい。","options":["難い","極めて","大方","同等"],"answer":"極めて","explanationKo":"「極めて」의 핵심 의미는 극히; 매우이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0980","prompt":"「進行・拡大などをある範囲で止める。また、人・物をその場所に残す。」という意味に最も近い語を選びなさい。","options":["止める","勝る","止まる","溢れる"],"answer":"止める","explanationKo":"「止める」의 핵심 의미는 머물게 하다; 그치게 하다; 범위에 한정하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','grammar',1,'〜とばかりに','{"pattern":"〜とばかりに","meaningKo":"마치 〜라는 듯이","explanation":"〜とばかりに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は待っていたとばかりに質問を始めた。","ko":"문맥에서 마치 〜라는 듯이의 의미로 쓰였다."},{"ja":"今が好機だとばかりに、各社が市場へ参入した。","ko":"이 문장도 마치 〜라는 듯이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','grammar',2,'〜と相まって','{"pattern":"〜と相まって","meaningKo":"〜와 어우러져","explanation":"〜と相まって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"技術の進歩と需要の増加と相まって、市場は急速に拡大した。","ko":"문맥에서 〜와 어우러져의 의미로 쓰였다."},{"ja":"本人の努力が周囲の支援と相まって、大きな成果につながった。","ko":"이 문장도 〜와 어우러져의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は待っていた（　）質問を始めた。","options":["〜に先駆けて","〜とばかりに","〜ながらに","〜に至っては"],"answer":"〜とばかりに","explanationKo":"문맥상 마치 〜라는 듯이를 나타내는 「〜とばかりに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n技術の進歩と需要の増加（　）、市場は急速に拡大した。","options":["〜と相まって","〜をよそに","〜に至っても","〜に先立って"],"answer":"〜と相まって","explanationKo":"문맥상 〜와 어우러져를 나타내는 「〜と相まって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその発言は社会に議論を起こさ（　）。","options":["〜を限りに","〜にあって","〜にこしたことはない","〜ないではおかない"],"answer":"〜ないではおかない","explanationKo":"문맥상 반드시 〜하게 만들다를 나타내는 「〜ないではおかない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-09','reading',1,'地域資源の活用','{"passage":"地域にある資源を活用することには、土地の特性を生かした価値を生み出せることという意義がある。ただし、短期の利益だけを求めると資源を損なうこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、維持に必要な費用と利用範囲を共有することが重要である。","questions":[{"prompt":"「地域資源の活用」について筆者が重要だと述べることは何か。","options":["維持に必要な費用と利用範囲を共有すること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"維持に必要な費用と利用範囲を共有すること","explanationKo":"본문의 결론은 維持に必要な費用と利用範囲を共有すること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["短期の利益だけを求めると資源を損なうこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"短期の利益だけを求めると資源を損なうこと","explanationKo":"본문에서는 短期の利益だけを求めると資源を損なうこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["土地の特性を生かした価値を生み出せること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"土地の特性を生かした価値を生み出せること","explanationKo":"地域にある資源を活用すること에는 土地の特性を生かした価値を生み出せること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1033","prompt":"「尽くす」の読み方として最も適切なものを選びなさい。","options":["つきる","とどめる","つらぬく","つくす"],"answer":"つくす","explanationKo":"「尽くす」는 「つくす」라고 읽는다. 뜻은 다하다; 힘을 쏟다; 모두 써버리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1080","prompt":"「止まる」の読み方として最も適切なものを選びなさい。","options":["あふれる","つく","とどまる","うかぶ"],"answer":"とどまる","explanationKo":"「止まる」는 「とどまる」라고 읽는다. 뜻은 머물다; 그치다; 범위를 넘지 않다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1120","prompt":"「襲う」の読み方として最も適切なものを選びなさい。","options":["そえる","おそう","いたむ","とどまる"],"answer":"おそう","explanationKo":"「襲う」는 「おそう」라고 읽는다. 뜻은 습격하다; 덮치다; 엄습하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1043","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの手続きは完了までに通常二週間程度を（　）。","options":["要する","沿う","強める","伴う"],"answer":"要する","explanationKo":"문맥상 「要する」가 가장 자연스럽다. 필요로 하다; 요하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1062","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n失敗を恐れて（　）になりすぎると、新しい挑戦ができなくなる。","options":["密か","正に","半端","臆病"],"answer":"臆病","explanationKo":"문맥상 「臆病」가 가장 자연스럽다. 겁이 많음; 소심함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1076","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n前年度と比べて売上は（　）減少したが、利益率は改善した。","options":["密接","多忙","若干","近々"],"answer":"若干","explanationKo":"문맥상 「若干」가 가장 자연스럽다. 약간; 다소; 약간 명라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1087","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの素材は水を（　）ため、雨天用の衣類にも使われている。","options":["強める","弾く","勝る","尽くす"],"answer":"弾く","explanationKo":"문맥상 「弾く」가 가장 자연스럽다. 튕기다; 튀겨 내다; 물리치다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1094","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ障害が（　）発生しているため、根本原因の調査が必要だ。","options":["度々","うんざり","単一","元来"],"answer":"度々","explanationKo":"문맥상 「度々」가 가장 자연스럽다. 자주; 여러 번라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1095","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n売上は国内市場が最も多く、（　）北米市場となっている。","options":["質素","専ら","簡素","次いで"],"answer":"次いで","explanationKo":"문맥상 「次いで」가 가장 자연스럽다. 이어서; 그다음으로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1140","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年の夏は例年より暑く、八月は（　）厳しい暑さだった。","options":["達者","最早","取り分け","優勢"],"answer":"取り分け","explanationKo":"문맥상 「取り分け」가 가장 자연스럽다. 특히; 유달리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1134","prompt":"「水面・空中などに浮いている。また、考え・記憶・表情などが心や顔に現れる。」という意味に最も近い語を選びなさい。","options":["要する","浮かぶ","沿う","記す"],"answer":"浮かぶ","explanationKo":"「浮かぶ」의 핵심 의미는 뜨다; 떠오르다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1145","prompt":"「人に知られないように、こっそり行うさま。」という意味に最も近い語を選びなさい。","options":["密か","度々","優勢","気まぐれ"],"answer":"密か","explanationKo":"「密か」의 핵심 의미는 은밀하다; 남몰래이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1146","prompt":"「力・程度・影響・態度などを以前より強くする。」という意味に最も近い語を選びなさい。","options":["追い込む","襲う","尽きる","強める"],"answer":"強める","explanationKo":"「強める」의 핵심 의미는 강화하다; 세게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1154","prompt":"「主となるもののそばに別のものを付け加える。言葉・品物・料理などを加える場合にもいう。」という意味に最も近い語を選びなさい。","options":["勝る","止まる","添える","告げる"],"answer":"添える","explanationKo":"「添える」의 핵심 의미는 곁들이다; 덧붙이다; 붙이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1164","prompt":"「事実・決定・時の到来などを相手に知らせる。」という意味に最も近い語を選びなさい。","options":["貫く","告げる","称する","止める"],"answer":"告げる","explanationKo":"「告げる」의 핵심 의미는 알리다; 고하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','grammar',1,'〜ないではおかない','{"pattern":"〜ないではおかない","meaningKo":"반드시 〜하게 만들다","explanation":"〜ないではおかない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この作品は見る者を感動させないではおかない。","ko":"문맥에서 반드시 〜하게 만들다의 의미로 쓰였다."},{"ja":"その発言は社会に議論を起こさないではおかない。","ko":"이 문장도 반드시 〜하게 만들다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','grammar',2,'〜ないではすまない','{"pattern":"〜ないではすまない","meaningKo":"〜하지 않고는 끝나지 않다","explanation":"〜ないではすまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"重大なミスなので、謝らないではすまない。","ko":"문맥에서 〜하지 않고는 끝나지 않다의 의미로 쓰였다."},{"ja":"規則を破った以上、責任を取らないではすまない。","ko":"이 문장도 〜하지 않고는 끝나지 않다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの作品は見る者を感動させ（　）。","options":["〜ないではおかない","〜を限りに","〜にあって","〜にこしたことはない"],"answer":"〜ないではおかない","explanationKo":"문맥상 반드시 〜하게 만들다를 나타내는 「〜ないではおかない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n重大なミスなので、謝ら（　）。","options":["〜にかたくない","〜にして","〜には及ばない","〜ないではすまない"],"answer":"〜ないではすまない","explanationKo":"문맥상 〜하지 않고는 끝나지 않다를 나타내는 「〜ないではすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n聞く（　）隣の会話を聞いていた。","options":["〜にしてはじめて","〜まじき","〜ともなく","〜にひきかえ"],"answer":"〜ともなく","explanationKo":"문맥상 딱히 〜하려는 것도 없이를 나타내는 「〜ともなく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-10','reading',1,'異議を受け止める','{"passage":"決定に対する異議を受け止めることには、見落とした条件や影響を再確認できることという意義がある。ただし、反対の数だけで判断すると論点が曖昧になることもある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、異議の根拠を決定の前提と照らし合わせることが重要である。","questions":[{"prompt":"「異議を受け止める」について筆者が重要だと述べることは何か。","options":["異議の根拠を決定の前提と照らし合わせること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"異議の根拠を決定の前提と照らし合わせること","explanationKo":"본문의 결론은 異議の根拠を決定の前提と照らし合わせること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["反対の数だけで判断すると論点が曖昧になること","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"反対の数だけで判断すると論点が曖昧になること","explanationKo":"본문에서는 反対の数だけで判断すると論点が曖昧になること 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["見落とした条件や影響を再確認できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"見落とした条件や影響を再確認できること","explanationKo":"決定に対する異議を受け止めること에는 見落とした条件や影響を再確認できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1204","prompt":"「溢れる」の読み方として最も適切なものを選びなさい。","options":["あふれる","おそう","つきる","おもむく"],"answer":"あふれる","explanationKo":"「溢れる」는 「あふれる」라고 읽는다. 뜻은 넘치다; 가득하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1212","prompt":"「貫く」の読み方として最も適切なものを選びなさい。","options":["つよめる","いたむ","とどまる","つらぬく"],"answer":"つらぬく","explanationKo":"「貫く」는 「つらぬく」라고 읽는다. 뜻은 관철하다; 끝까지 지키다; 꿰뚫다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1226","prompt":"「込める」の読み方として最も適切なものを選びなさい。","options":["つらぬく","つくす","こめる","とどめる"],"answer":"こめる","explanationKo":"「込める」는 「こめる」라고 읽는다. 뜻은 담다; 넣다; 힘을 주다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1228","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n最初から（　）を求めるより、改善を重ねる方が現実的だ。","options":["達者","完璧","一気","気軽"],"answer":"完璧","explanationKo":"문맥상 「完璧」가 가장 자연스럽다. 완벽라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1229","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の要望に（　）形で画面構成を見直した。","options":["沿う","追い込む","弾く","告げる"],"answer":"沿う","explanationKo":"문맥상 「沿う」가 가장 자연스럽다. 따르다; ~을 따라가다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1231","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその建物は曲線を生かした（　）なデザインで知られている。","options":["有望","臆病","正に","優美"],"answer":"優美","explanationKo":"문맥상 「優美」가 가장 자연스럽다. 우아함; 아름답고 품위 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1241","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は外国語が（　）で、会議でも通訳なしで意見を述べる。","options":["同等","無礼","達者","断然"],"answer":"達者","explanationKo":"문맥상 「達者」가 가장 자연스럽다. 능숙함; 건강함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1261","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ説明を何度も聞かされて、さすがに（　）した。","options":["公然","うんざり","ほっと","手軽"],"answer":"うんざり","explanationKo":"문맥상 「うんざり」가 가장 자연스럽다. 진절머리 남; 싫증이 남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1267","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長時間同じ姿勢で作業したため、腰が（　）ようになった。","options":["痛む","勝る","止まる","添える"],"answer":"痛む","explanationKo":"문맥상 「痛む」가 가장 자연스럽다. 아프다; 상하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1273","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は高い収入を得ても（　）な生活を続けている。","options":["元来","うんざり","手軽","質素"],"answer":"質素","explanationKo":"문맥상 「質素」가 가장 자연스럽다. 검소함; 소박함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1262","prompt":"「能力・品質・程度などが他より優れている。」という意味に最も近い語を選びなさい。","options":["漂う","交わす","勝る","込める"],"answer":"勝る","explanationKo":"「勝る」의 핵심 의미는 능가하다; 더 낫다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1282","prompt":"「人・動物などをある場所へ追って入れる。また、相手を逃げ道のない困難な状況に陥らせる。」という意味に最も近い語を選びなさい。","options":["赴く","追い込む","弾く","告げる"],"answer":"追い込む","explanationKo":"「追い込む」의 핵심 의미는 몰아넣다; 궁지로 몰다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1283","prompt":"「ある場所・任務・方向へ向かって行く。」という意味に最も近い語を選びなさい。","options":["赴く","沿う","尽くす","強める"],"answer":"赴く","explanationKo":"「赴く」의 핵심 의미는 가다; 향하다; 부임하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1300","prompt":"「『嘘をつく』『ため息をつく』など、一定の表現で口から言葉・息などを出す意味を表す。」という意味に最も近い語を選びなさい。","options":["止める","引き起こす","伴う","吐く"],"answer":"吐く","explanationKo":"「吐く」의 핵심 의미는 (거짓말·한숨 등을) 내뱉다; 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1318","prompt":"「緊張・心配などが解けて安心するさま。」という意味に最も近い語を選びなさい。","options":["断然","有望","ほっと","単調"],"answer":"ほっと","explanationKo":"「ほっと」의 핵심 의미는 안도하여 마음이 놓이는 모양이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','grammar',1,'〜ともなく','{"pattern":"〜ともなく","meaningKo":"딱히 〜하려는 것도 없이","explanation":"〜ともなく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"見るともなく窓の外を眺めていた。","ko":"문맥에서 딱히 〜하려는 것도 없이의 의미로 쓰였다."},{"ja":"聞くともなく隣の会話を聞いていた。","ko":"이 문장도 딱히 〜하려는 것도 없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','grammar',2,'〜ながらに','{"pattern":"〜ながらに","meaningKo":"〜인 채로; 〜하면서도","explanation":"〜ながらに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は生まれながらに豊かな才能を備えていた。","ko":"문맥에서 〜인 채로; 〜하면서도의 의미로 쓰였다."},{"ja":"この町には昔ながらに受け継がれた慣習が残る。","ko":"이 문장도 〜인 채로; 〜하면서도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n見る（　）窓の外を眺めていた。","options":["〜にひきかえ","〜にしてはじめて","〜まじき","〜ともなく"],"answer":"〜ともなく","explanationKo":"문맥상 딱히 〜하려는 것도 없이를 나타내는 「〜ともなく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は生まれ（　）豊かな才能を備えていた。","options":["〜にかこつけて","〜べく","〜ながらに","〜に至って"],"answer":"〜ながらに","explanationKo":"문맥상 〜인 채로; 〜하면서도를 나타내는 「〜ながらに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n住民の反対（　）、工事は予定どおり始まった。","options":["〜べくもない","〜をよそに","〜に至っては","〜に則って"],"answer":"〜をよそに","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をよそに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-11','reading',1,'学習内容を選び直す','{"passage":"学習する内容を定期的に選び直すことには、目標に必要な知識へ時間を集中できることという意義がある。ただし、苦手という理由だけで重要項目を外すこともある。実施する際は、目標と判断基準を関係者の間で明らかにし、結果を見ながら方法を調整しなければならない。したがって、試験での役割と現在の理解度を照らして優先順位を決めることが重要である。","questions":[{"prompt":"「学習内容を選び直す」について筆者が重要だと述べることは何か。","options":["試験での役割と現在の理解度を照らして優先順位を決めること","最初の方法を無条件に守ること","結果を確認しないこと","判断基準を一人だけで決めること"],"answer":"試験での役割と現在の理解度を照らして優先順位を決めること","explanationKo":"본문의 결론은 試験での役割と現在の理解度を照らして優先順位を決めること 것이 중요하다는 내용이다."},{"prompt":"本文で指摘されている注意点は何か。","options":["苦手という理由だけで重要項目を外すこと","必ず費用がゼロになること","関係者が不要になること","目的が自動的に決まること"],"answer":"苦手という理由だけで重要項目を外すこと","explanationKo":"본문에서는 苦手という理由だけで重要項目を外すこと 가능성을 주의점으로 든다."},{"prompt":"本文の内容と一致するものはどれか。","options":["目標に必要な知識へ時間を集中できること","方法は結果にかかわらず変更してはならない","判断基準を共有する必要はない","実施後の確認は不要である"],"answer":"目標に必要な知識へ時間を集中できること","explanationKo":"学習する内容を定期的に選び直すこと에는 目標に必要な知識へ時間を集中できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
